(() => {
  "use strict";
  const catalog = {"My work on Iraq's oil dependence, government finances and economic outlook. A Python application and bachelor's thesis in progress.":{"ro":"Cercetarea mea despre dependența de petrol, finanțele publice și perspectivele economice ale Irakului. O aplicație Python și o lucrare de licență în dezvoltare.","ar":"بحثي حول اعتماد العراق على النفط وماليته العامة وآفاقه الاقتصادية. تطبيق بلغة Python ومشروع تخرج قيد التطوير."},"Iraq’s Economic Outlook | Nooruldeen’s thesis":{"ro":"Perspectivele economice ale Irakului | Lucrarea de licență a lui Nooruldeen","ar":"الآفاق الاقتصادية للعراق | مشروع تخرج نورالدين"},"Skip to my project":{"ro":"Sari la proiectul meu","ar":"انتقل إلى مشروعي"},"Back to my website":{"ro":"Înapoi la site-ul meu","ar":"العودة إلى موقعي"},"My portrait":{"ro":"Portretul meu","ar":"صورتي الشخصية"},"Al Sammarraie":{"ro":"Al Sammarraie","ar":"السامرائي"},"Noor":{"ro":"Noor","ar":"نور"},"uldeen":{"ro":"uldeen","ar":"الدين"},"MY THESIS / WORK IN PROGRESS":{"ro":"LUCRAREA MEA / ÎN DEZVOLTARE","ar":"مشروع تخرجي / قيد التطوير"},"PROJECT FILES":{"ro":"FIȘIERELE PROIECTULUI","ar":"ملفات المشروع"},"Main navigation":{"ro":"Navigare principală","ar":"التنقل الرئيسي"},"HOME":{"ro":"ACASĂ","ar":"الرئيسية"},"ABOUT":{"ro":"DESPRE","ar":"نبذة"},"WORK":{"ro":"LUCRĂRI","ar":"الأعمال"},"THESIS":{"ro":"LICENȚĂ","ar":"مشروع التخرج"},"CONTACT":{"ro":"CONTACT","ar":"تواصل"},"DATA":{"ro":"DATE","ar":"بيانات"},"AND CODE":{"ro":"ȘI COD","ar":"وبرمجة"},"IRAQ ECONOMIC OBSERVATORY":{"ro":"OBSERVATORUL ECONOMIC AL IRAKULUI","ar":"المرصد الاقتصادي العراقي"},"Iraq’s":{"ro":"Perspectivele","ar":"الآفاق"},"economic":{"ro":"economice","ar":"الاقتصادية"},"outlook":{"ro":"ale Irakului","ar":"للعراق"},"Iraq’s Economic Outlook: Building an Economic Analysis System with Iraq as a Case Study":{"ro":"Perspectivele economice ale Irakului: Construirea unui sistem de analiză economică, cu Irakul ca studiu de caz","ar":"الآفاق الاقتصادية للعراق: بناء نظام للتحليل الاقتصادي باستخدام العراق كدراسة حالة"},"I grew up in Iraq, and I want to understand how its oil wealth relates to pressure on public finances and the difficulty of building a more diverse economy. This is the Python application and research I am developing for my bachelor's thesis at ASE.":{"ro":"Am crescut în Irak și vreau să înțeleg legătura dintre bogăția sa petrolieră, presiunea asupra finanțelor publice și dificultatea construirii unei economii mai diversificate. Acestea sunt aplicația Python și cercetarea pe care le dezvolt pentru lucrarea mea de licență la ASE.","ar":"نشأت في العراق، وأريد أن أفهم علاقة ثروته النفطية بالضغوط على المالية العامة وصعوبة بناء اقتصاد أكثر تنوعًا. هذا هو تطبيق Python والبحث اللذان أعمل عليهما لمشروع تخرجي في أكاديمية بوخارست للدراسات الاقتصادية."},"Explore my prototype":{"ro":"Explorează prototipul meu","ar":"استكشف النموذج الأولي"},"Read my research plan":{"ro":"Citește planul meu de cercetare","ar":"اقرأ خطة بحثي"},"Economic Informatics · ASE Bucharest":{"ro":"Informatică Economică · ASE București","ar":"المعلوماتية الاقتصادية · أكاديمية بوخارست للدراسات الاقتصادية"},"My intended defence: July 2027":{"ro":"Susținerea planificată: iulie 2027","ar":"موعد المناقشة المخطط له: يوليو 2027"},"The Malwiya minaret in Samarra, Iraq, photographed by David Stanley":{"ro":"Minaretul Malwiya din Samarra, Irak, fotografiat de David Stanley","ar":"مئذنة الملوية في سامراء، العراق، بعدسة David Stanley"},"SAMARRA, IRAQ":{"ro":"SAMARRA, IRAK","ar":"سامراء، العراق"},"Photograph: David Stanley.":{"ro":"Fotografie: David Stanley.","ar":"تصوير: David Stanley."},"MY COUNTRY":{"ro":"ȚARA MEA","ar":"بلدي"},"MY QUESTIONS":{"ro":"ÎNTREBĂRILE MELE","ar":"أسئلتي"},"The foundations of my thesis":{"ro":"Fundamentele lucrării mele de licență","ar":"أسس مشروع تخرجي"},"A starting point":{"ro":"Un punct de pornire","ar":"نقطة البداية"},"Understanding Iraq’s economy in the years after 2003.":{"ro":"Înțelegerea economiei Irakului în anii de după 2003.","ar":"فهم اقتصاد العراق في السنوات التي تلت عام 2003."},"Economic analysis":{"ro":"Analiză economică","ar":"التحليل الاقتصادي"},"Reading the evidence, following the sources and asking better questions.":{"ro":"Examinarea dovezilor, urmărirea surselor și formularea unor întrebări mai bune.","ar":"قراءة الأدلة وتتبع المصادر وطرح أسئلة أفضل."},"A Python system":{"ro":"Un sistem Python","ar":"نظام بلغة Python"},"Bringing data, methods and an interactive application together.":{"ro":"Date, metode și o aplicație interactivă reunite într-un singur sistem.","ar":"جمع البيانات والأساليب والتطبيق التفاعلي في نظام واحد."},"Possible futures":{"ro":"Viitoruri posibile","ar":"آفاق محتملة"},"Exploring forecasts, uncertainty and clearly stated scenarios.":{"ro":"Explorarea prognozelor, a incertitudinii și a scenariilor cu ipoteze explicite.","ar":"استكشاف التنبؤات وعدم اليقين والسيناريوهات ذات الافتراضات الواضحة."},"Sections in my thesis project":{"ro":"Secțiunile proiectului meu de licență","ar":"أقسام مشروع تخرجي"},"THE QUESTIONS":{"ro":"ÎNTREBĂRILE","ar":"الأسئلة"},"TRY THE PREVIEW":{"ro":"ÎNCEARCĂ PREVIZUALIZAREA","ar":"جرّب المعاينة"},"DATA & SOURCES":{"ro":"DATE ȘI SURSE","ar":"البيانات والمصادر"},"WHAT'S NEXT":{"ro":"CE URMEAZĂ","ar":"الخطوات القادمة"},"02 / WHAT I WANT TO UNDERSTAND":{"ro":"02 / CE VREAU SĂ ÎNȚELEG","ar":"02 / ما أريد فهمه"},"DATA / ECONOMICS / CODE":{"ro":"DATE / ECONOMIE / COD","ar":"بيانات / اقتصاد / برمجة"},"I want to understand":{"ro":"Vreau să înțeleg","ar":"أريد أن أفهم"},"Iraq better.":{"ro":"Irakul mai bine.","ar":"العراق بشكل أفضل."},"What interests me is how Iraq has developed after the US-led invasion in 2003 and the fall of Saddam Hussein's regime. I want to understand why having valuable oil resources has not made development straightforward, look at the evidence carefully, and build a tool that helps me explore the questions.":{"ro":"Mă interesează cum s-a dezvoltat Irakul după invazia condusă de SUA în 2003 și căderea regimului lui Saddam Hussein. Vreau să înțeleg de ce resursele petroliere valoroase nu au făcut dezvoltarea simplă, să examinez atent dovezile și să construiesc un instrument care mă ajută să explorez aceste întrebări.","ar":"ما يهمني هو تطور العراق بعد الغزو الذي قادته الولايات المتحدة عام 2003 وسقوط نظام صدام حسين. أريد فهم سبب تعقّد التنمية رغم الموارد النفطية القيّمة، وقراءة الأدلة بعناية، وبناء أداة تساعدني على استكشاف هذه الأسئلة."},"MY PROVISIONAL THESIS TITLE":{"ro":"TITLUL MEU PROVIZORIU","ar":"عنوان مشروع تخرجي الحالي"},"I have chosen this title for now. Professor Uscatu has agreed to coordinate my thesis, and I will confirm the title and final scope with him.":{"ro":"Am ales acest titlu pentru moment. Profesorul Uscatu a acceptat să îmi coordoneze lucrarea, iar titlul și delimitarea finală vor fi confirmate împreună cu el.","ar":"اخترت هذا العنوان في الوقت الحالي. وافق الأستاذ Uscatu على الإشراف على مشروع تخرجي، وسأؤكد معه العنوان والنطاق النهائيين."},"How has Iraq developed since 2003?":{"ro":"Cum s-a dezvoltat Irakul din 2003?","ar":"كيف تطور العراق منذ عام 2003؟"},"I chose 2003 because it marks the invasion and the fall of Saddam Hussein's regime. I want to follow the economy after that change, using growth, real GDP per person and manufacturing.":{"ro":"Am ales anul 2003 deoarece marchează invazia și căderea regimului lui Saddam Hussein. Vreau să urmăresc economia după această schimbare, folosind creșterea economică, PIB-ul real pe persoană și industria prelucrătoare.","ar":"اخترت عام 2003 لأنه يمثل الغزو وسقوط نظام صدام حسين. أريد تتبع الاقتصاد بعد هذا التغيير من خلال النمو والناتج المحلي الإجمالي الحقيقي للفرد والصناعة التحويلية."},"What puts pressure on the budget?":{"ro":"Ce pune presiune pe buget?","ar":"ما الذي يضغط على الموازنة؟"},"I am examining recorded revenue and spending month by month, while keeping oil-related income and accounting adjustments visible.":{"ro":"Examinez veniturile și cheltuielile înregistrate, lună de lună, păstrând vizibile veniturile legate de petrol și ajustările contabile.","ar":"أدرس الإيرادات والنفقات المسجلة شهرًا بشهر، مع إبقاء الدخل المرتبط بالنفط والتعديلات المحاسبية ظاهرين."},"Can a forecast improve on a simple baseline?":{"ro":"Poate o prognoză depăși un reper simplu?","ar":"هل يمكن لتنبؤ أن يتفوق على مرجع بسيط؟"},"I compare five methods on the same months and inspect their errors and uncertainty before choosing a final model.":{"ro":"Compar cinci metode pe aceleași luni și examinez erorile și incertitudinea înainte să aleg modelul final.","ar":"أقارن خمس طرق على الأشهر نفسها، وأراجع أخطاءها وعدم اليقين فيها قبل اختيار النموذج النهائي."},"How much do the assumptions change the outlook?":{"ro":"Cât de mult schimbă ipotezele perspectivele?","ar":"إلى أي مدى تغيّر الافتراضات الآفاق؟"},"I can change an oil-price or spending assumption and calculate the resulting pressure around a published annual baseline.":{"ro":"Pot schimba o ipoteză privind prețul petrolului sau cheltuielile și calcula presiunea rezultată în raport cu un scenariu anual de referință publicat.","ar":"يمكنني تغيير افتراض حول سعر النفط أو الإنفاق وحساب الضغط الناتج مقارنة بمسار سنوي مرجعي منشور."},"I want to understand what the evidence shows. A country comparison can help me spot a pattern, but it cannot prove what caused it.":{"ro":"Vreau să înțeleg ce arată dovezile. Compararea țărilor poate evidenția un tipar, dar nu poate demonstra cauza lui.","ar":"أريد فهم ما توضحه الأدلة. قد تساعد مقارنة البلدان على ملاحظة نمط، لكنها لا تثبت سببه."},"03 / THE APPLICATION I AM BUILDING":{"ro":"03 / APLICAȚIA PE CARE O CONSTRUIESC","ar":"03 / التطبيق الذي أبنيه"},"WORKING PROTOTYPE":{"ro":"PROTOTIP FUNCȚIONAL","ar":"نموذج أولي يعمل"},"Try the work":{"ro":"Încearcă proiectul","ar":"جرّب المشروع"},"for yourself.":{"ro":"chiar tu.","ar":"بنفسك."},"This is a browser preview of my saved results and the controls I have prepared. I am keeping the Python application in my private repository while I build it. I want to share it more widely when it is ready.":{"ro":"Aceasta este o previzualizare în browser a rezultatelor salvate și a comenzilor pe care le-am pregătit. Păstrez aplicația Python în depozitul meu privat cât timp o dezvolt. Vreau să o distribui mai larg când va fi pregătită.","ar":"هذه معاينة في المتصفح لنتائجي المحفوظة وأدوات التحكم التي أعددتها. أحتفظ بتطبيق Python في مستودعي الخاص أثناء تطويره، وأريد إتاحته بشكل أوسع عندما يصبح جاهزًا."},"MY RESEARCH WORKBENCH":{"ro":"ATELIERUL MEU DE CERCETARE","ar":"مساحة البحث التفاعلية"},"Saved source snapshots: October 2026":{"ro":"Date sursă salvate: octombrie 2026","ar":"نسخ المصادر المحفوظة: أكتوبر 2026"},"Loading the saved research preview…":{"ro":"Se încarcă previzualizarea rezultatelor salvate…","ar":"جارٍ تحميل معاينة البحث المحفوظة…"},"Enable JavaScript to explore the saved results. The research plan and presentation are available below.":{"ro":"Activează JavaScript pentru a explora rezultatele salvate. Planul de cercetare și informațiile despre prezentare sunt mai jos.","ar":"فعّل JavaScript لاستكشاف النتائج المحفوظة. ستجد خطة البحث ومعلومات العرض أدناه."},"Explore my project":{"ro":"Explorează proiectul meu","ar":"استكشف مشروعي"},"Iraq over time":{"ro":"Irakul în timp","ar":"العراق عبر الزمن"},"Monthly forecasts":{"ro":"Prognoze lunare","ar":"التنبؤات الشهرية"},"Budget scenarios":{"ro":"Scenarii bugetare","ar":"سيناريوهات الموازنة"},"Country comparisons":{"ro":"Comparații între țări","ar":"مقارنة البلدان"},"The longer economic picture":{"ro":"Imaginea economică pe termen lung","ar":"الصورة الاقتصادية على المدى الطويل"},"I keep the history from 2003 and compare the yearly figures as they were published.":{"ro":"Păstrez istoricul din 2003 și compar valorile anuale în forma publicată.","ar":"أحتفظ بالسجل منذ عام 2003 وأقارن البيانات السنوية كما نُشرت."},"How to read this view":{"ro":"Cum se citește această vizualizare","ar":"كيف تقرأ هذا العرض"},"Real GDP per person:":{"ro":"PIB real pe persoană:","ar":"الناتج المحلي الإجمالي الحقيقي للفرد:"},"economic output divided by population, adjusted to 2015 prices. It is not household income.":{"ro":"producția economică împărțită la populație, ajustată la prețurile din 2015. Nu reprezintă venitul gospodăriilor.","ar":"الناتج الاقتصادي مقسومًا على السكان، بأسعار عام 2015. ولا يمثل دخل الأسر."},"Real GDP growth:":{"ro":"Creșterea PIB-ului real:","ar":"نمو الناتج المحلي الإجمالي الحقيقي:"},"the annual percentage change in economic output after price changes.":{"ro":"variația procentuală anuală a producției economice, după ajustarea pentru schimbările de preț.","ar":"التغير السنوي في الناتج الاقتصادي كنسبة مئوية بعد تعديل تغيرات الأسعار."},"Manufacturing share:":{"ro":"Ponderea industriei prelucrătoare:","ar":"حصة الصناعة التحويلية:"},"manufacturing value added as a percentage of GDP.":{"ro":"valoarea adăugată a industriei prelucrătoare ca procent din PIB.","ar":"القيمة المضافة للصناعة التحويلية كنسبة من الناتج المحلي الإجمالي."},"Oil rents:":{"ro":"Rente petroliere:","ar":"الريع النفطي:"},"the estimated value of oil production after production costs, as a percentage of GDP. This is not government oil revenue.":{"ro":"valoarea estimată a producției petroliere după costurile de producție, ca procent din PIB. Nu reprezintă veniturile petroliere ale guvernului.","ar":"القيمة المقدرة لإنتاج النفط بعد تكاليف الإنتاج، كنسبة من الناتج المحلي الإجمالي. ولا تمثل الإيرادات النفطية الحكومية."},"Each point is a published annual observation. Missing years stay missing. Hover or tap a line to inspect the country, year and saved value.":{"ro":"Fiecare punct este o observație anuală publicată. Anii fără date rămân fără date. Treci cursorul peste o linie sau atinge-o pentru a vedea țara, anul și valoarea salvată.","ar":"كل نقطة تمثل مشاهدة سنوية منشورة. تبقى السنوات المفقودة بلا بيانات. مرّر المؤشر فوق الخط أو المسه لعرض البلد والسنة والقيمة المحفوظة."},"Indicator":{"ro":"Indicator","ar":"المؤشر"},"Real GDP per person":{"ro":"PIB real pe persoană","ar":"الناتج المحلي الإجمالي الحقيقي للفرد"},"Real GDP growth":{"ro":"Creșterea PIB-ului real","ar":"نمو الناتج المحلي الإجمالي الحقيقي"},"Manufacturing share":{"ro":"Ponderea industriei prelucrătoare","ar":"حصة الصناعة التحويلية"},"Oil rents":{"ro":"Rente petroliere","ar":"الريع النفطي"},"Iraq is highlighted. Every loaded comparison country stays visible in teal. Hover or tap a line for its period and precise value.":{"ro":"Irakul este evidențiat. Toate țările de comparație încărcate rămân vizibile în verde turcoaz. Treci cursorul peste o linie sau atinge-o pentru perioada și valoarea exactă.","ar":"العراق مميز بلون مختلف. تبقى جميع بلدان المقارنة المحمّلة ظاهرة باللون الفيروزي. مرّر المؤشر فوق الخط أو المسه لعرض الفترة والقيمة الدقيقة."},"Does a more complex model help?":{"ro":"Ajută un model mai complex?","ar":"هل يفيد نموذج أكثر تعقيدًا؟"},"I test five methods on the same 24 months, July 2024–June 2026. Each predicts one month ahead. MAE is the average size of the errors; RMSE gives bigger mistakes more weight. Both are in trillion Iraqi dinars.":{"ro":"Testez cinci metode pe aceleași 24 de luni, iulie 2024–iunie 2026. Fiecare prognozează cu o lună înainte. MAE este mărimea medie a erorilor; RMSE acordă greșelilor mari o pondere mai mare. Ambele sunt exprimate în trilioane de dinari irakieni.","ar":"أختبر خمس طرق على الأشهر الـ24 نفسها، من يوليو 2024 إلى يونيو 2026. تتنبأ كل طريقة بالشهر التالي. MAE هو متوسط حجم الأخطاء، بينما يمنح RMSE الأخطاء الكبيرة وزنًا أكبر. كلاهما مقاس بتريليون دينار عراقي."},"How to read the forecast comparison":{"ro":"Cum se citește comparația prognozelor","ar":"كيف تقرأ مقارنة التنبؤات"},"MAE:":{"ro":"MAE:","ar":"MAE:"},"average absolute prediction error. Lower is better.":{"ro":"eroarea absolută medie de prognoză. O valoare mai mică este mai bună.","ar":"متوسط الخطأ المطلق للتنبؤ. القيمة الأقل أفضل."},"RMSE:":{"ro":"RMSE:","ar":"RMSE:"},"prediction error with more weight given to large mistakes. Lower is better.":{"ro":"eroarea de prognoză care acordă mai multă greutate greșelilor mari. O valoare mai mică este mai bună.","ar":"مقياس لخطأ التنبؤ يعطي الأخطاء الكبيرة وزنًا أكبر. القيمة الأقل أفضل."},"Trillion IQD:":{"ro":"Trilioane IQD:","ar":"تريليون دينار عراقي:"},"one trillion Iraqi dinars, at the prices of that period.":{"ro":"un trilion de dinari irakieni, la prețurile perioadei respective.","ar":"تريليون دينار عراقي بأسعار الفترة المعنية."},"95% prediction interval:":{"ro":"Interval de predicție de 95%:","ar":"فاصل تنبؤ بنسبة 95%:"},"the model’s uncertainty range for a future observation, under its assumptions.":{"ro":"intervalul de incertitudine al modelului pentru o observație viitoare, în condițiile ipotezelor sale.","ar":"نطاق عدم اليقين في النموذج لمشاهدة مستقبلية، وفقًا لافتراضاته."},"The table compares all five methods on the same 24 historical months. The chart shows the selected model’s saved July–September 2026 predictions. It does not fit a new model when you change the selection.":{"ro":"Tabelul compară toate cele cinci metode pe aceleași 24 de luni istorice. Graficul arată prognozele salvate ale modelului selectat pentru iulie–septembrie 2026. Schimbarea selecției nu estimează un model nou.","ar":"يقارن الجدول الطرق الخمس على الأشهر التاريخية الـ24 نفسها. يعرض الرسم تنبؤات النموذج المختار المحفوظة ليوليو–سبتمبر 2026. لا تتم ملاءمة نموذج جديد عند تغيير الاختيار."},"My initial monthly revenue forecast comparison":{"ro":"Comparația mea inițială a prognozelor lunare de venituri","ar":"مقارنتي الأولية لتنبؤات الإيرادات الشهرية"},"Method":{"ro":"Metodă","ar":"الطريقة"},"MAE":{"ro":"MAE","ar":"MAE"},"RMSE":{"ro":"RMSE","ar":"RMSE"},"Targets":{"ro":"Luni evaluate","ar":"الأشهر المقيمة"},"Last month":{"ro":"Luna precedentă","ar":"الشهر السابق"},"Same month last year":{"ro":"Aceeași lună anul trecut","ar":"الشهر نفسه من العام السابق"},"AR(1)":{"ro":"AR(1)","ar":"AR(1)"},"LOWEST MAE":{"ro":"CEL MAI MIC MAE","ar":"أقل MAE"},"ARIMA(1,1,1)":{"ro":"ARIMA(1,1,1)","ar":"ARIMA(1,1,1)"},"LOWEST RMSE":{"ro":"CEL MAI MIC RMSE","ar":"أقل RMSE"},"SARIMA(1,0,0)(0,1,1)[12]":{"ro":"SARIMA(1,0,0)(0,1,1)[12]","ar":"SARIMA(1,0,0)(0,1,1)[12]"},"WHAT I FOUND SO FAR":{"ro":"CE AM AFLAT PÂNĂ ACUM","ar":"ما توصلت إليه حتى الآن"},"AR(1) has the lowest MAE. ARIMA(1,1,1) has the lowest RMSE. I still need to check the model assumptions and remaining patterns in the errors before making my final choice.":{"ro":"AR(1) are cel mai mic MAE. ARIMA(1,1,1) are cel mai mic RMSE. Încă trebuie să verific ipotezele modelelor și tiparele rămase în erori înainte de alegerea finală.","ar":"يحقق AR(1) أقل MAE، ويحقق ARIMA(1,1,1) أقل RMSE. ما زلت بحاجة إلى مراجعة افتراضات النماذج والأنماط المتبقية في الأخطاء قبل اختياري النهائي."},"Inspect a fitted method":{"ro":"Examinează o metodă estimată","ar":"افحص نموذجًا تمت ملاءمته"},"These saved predictions use data ending in June 2026 to look at July–September. They are not a fresh forecast made today. The shaded 95% band shows uncertainty under the model's assumptions. So far, I have tested accuracy one month ahead.":{"ro":"Aceste prognoze salvate folosesc date până în iunie 2026 pentru iulie–septembrie. Nu sunt prognoze noi făcute astăzi. Banda umbrită de 95% arată incertitudinea în condițiile ipotezelor modelului. Până acum am testat precizia la un orizont de o lună.","ar":"تستخدم هذه التنبؤات المحفوظة بيانات تنتهي في يونيو 2026 للنظر في يوليو–سبتمبر. وهي ليست تنبؤات جديدة أُعدت اليوم. يعرض الشريط المظلل بنسبة 95% عدم اليقين وفق افتراضات النموذج. اختبرت الدقة حتى الآن لشهر واحد إلى الأمام."},"What if oil prices fall?":{"ro":"Ce se întâmplă dacă scade prețul petrolului?","ar":"ماذا لو انخفضت أسعار النفط؟"},"I use the IMF's April 2026 yearly projections as a starting point. Change the assumptions to see how the budget balance changes.":{"ro":"Folosesc proiecțiile anuale ale FMI din aprilie 2026 ca punct de pornire. Schimbă ipotezele pentru a vedea cum se modifică soldul bugetar.","ar":"أستخدم التوقعات السنوية لصندوق النقد الدولي الصادرة في أبريل 2026 كنقطة بداية. غيّر الافتراضات لترى تغير رصيد الموازنة."},"How to read the budget scenario":{"ro":"Cum se citește scenariul bugetar","ar":"كيف تقرأ سيناريو الموازنة"},"Baseline:":{"ro":"Scenariu de referință:","ar":"المسار المرجعي:"},"the balance calculated from the IMF’s published annual revenue, spending and GDP projections.":{"ro":"soldul calculat din proiecțiile anuale publicate de FMI pentru venituri, cheltuieli și PIB.","ar":"الرصيد المحسوب من توقعات الإيرادات والنفقات والناتج المحلي الإجمالي السنوية المنشورة من صندوق النقد الدولي."},"Scenario:":{"ro":"Scenariu:","ar":"السيناريو:"},"the balance after your price assumption changes the selected share of revenue.":{"ro":"soldul după ce ipoteza ta de preț modifică ponderea selectată a veniturilor.","ar":"الرصيد بعد أن يغير افتراضك للسعر الحصة المحددة من الإيرادات."},"Balance as % of GDP:":{"ro":"Sold ca % din PIB:","ar":"الرصيد كنسبة من الناتج المحلي الإجمالي:"},"revenue minus spending, divided by fixed baseline GDP. Negative values show a deficit; positive values show a surplus.":{"ro":"venituri minus cheltuieli, împărțite la PIB-ul fix al scenariului de referință. Valorile negative indică un deficit; cele pozitive, un excedent.","ar":"الإيرادات ناقص النفقات، مقسومة على الناتج المحلي الإجمالي المرجعي الثابت. القيم السالبة تعني عجزًا والموجبة تعني فائضًا."},"Percentage points:":{"ro":"Puncte procentuale:","ar":"النقاط المئوية:"},"the difference between the two balance percentages, not a percentage change.":{"ro":"diferența dintre cele două procente ale soldului, nu o variație procentuală.","ar":"الفرق بين نسبتي الرصيد، وليس تغيرًا نسبيًا بالمئة."},"The price-sensitive revenue share is an assumption you choose. Spending, export quantities, other revenue, GDP and the exchange rate stay fixed in this calculation.":{"ro":"Ponderea veniturilor sensibile la preț este o ipoteză aleasă de tine. Cheltuielile, cantitățile exportate, alte venituri, PIB-ul și cursul de schimb rămân fixe în acest calcul.","ar":"حصة الإيرادات الحساسة للسعر افتراض تختاره أنت. تبقى النفقات وكميات التصدير والإيرادات الأخرى والناتج المحلي الإجمالي وسعر الصرف ثابتة في هذا الحساب."},"Oil-price change":{"ro":"Schimbarea prețului petrolului","ar":"تغير سعر النفط"},"A negative value assumes a fall in oil prices.":{"ro":"O valoare negativă presupune o scădere a prețului petrolului.","ar":"تفترض القيمة السالبة انخفاض أسعار النفط."},"Assumed price-sensitive revenue share":{"ro":"Pondere presupusă a veniturilor sensibile la preț","ar":"الحصة المفترضة للإيرادات الحساسة للسعر"},"The share of revenue assumed to respond to that price change.":{"ro":"Partea veniturilor presupusă a reacționa la acea schimbare de preț.","ar":"حصة الإيرادات التي نفترض استجابتها لذلك التغير في السعر."},"I keep spending, export quantities, other revenue, GDP and the exchange rate fixed here. I choose the share of revenue that responds to oil prices. This shows what happens under those assumptions; it does not say how likely the scenario is.":{"ro":"Păstrez aici fixe cheltuielile, cantitățile exportate, alte venituri, PIB-ul și cursul de schimb. Aleg ponderea veniturilor care reacționează la prețul petrolului. Calculul arată ce se întâmplă în aceste condiții, nu cât de probabil este scenariul.","ar":"أُبقي النفقات وكميات التصدير والإيرادات الأخرى والناتج المحلي الإجمالي وسعر الصرف ثابتة هنا. أختار حصة الإيرادات التي تتأثر بسعر النفط. يوضح الحساب ما يحدث وفق هذه الافتراضات، ولا يحدد احتمال وقوع السيناريو."},"Download this scenario and its assumptions":{"ro":"Descarcă acest scenariu și ipotezele lui","ar":"نزّل هذا السيناريو وافتراضاته"},"What makes a country comparable?":{"ro":"Ce face o țară comparabilă?","ar":"ما الذي يجعل بلدًا قابلًا للمقارنة؟"},"I compare countries using their 2003–2007 oil rents, real GDP per person and manufacturing. Change how much each feature matters to see how the ranking changes. My calculation uses log GDP per person to reduce the effect of very large income differences.":{"ro":"Compar țările pe baza rentelor petroliere, PIB-ului real pe persoană și industriei prelucrătoare din 2003–2007. Schimbă importanța fiecărei caracteristici pentru a vedea clasamentul. Calculul folosește logaritmul PIB-ului pe persoană pentru a reduce efectul diferențelor foarte mari de venit.","ar":"أقارن البلدان باستخدام الريع النفطي والناتج المحلي الإجمالي الحقيقي للفرد والصناعة التحويلية خلال 2003–2007. غيّر أهمية كل خاصية لترى تغير الترتيب. يستخدم الحساب لوغاريتم الناتج المحلي للفرد لتقليل أثر الفروق الكبيرة جدًا في الدخل."},"How to read the country comparison":{"ro":"Cum se citește comparația între țări","ar":"كيف تقرأ مقارنة البلدان"},"Iraq is the reference, with a distance of zero. Every loaded comparison country is listed. The features come from the 2003–2007 period.":{"ro":"Irakul este reperul, cu distanța zero. Toate țările de comparație încărcate sunt enumerate. Caracteristicile provin din perioada 2003–2007.","ar":"العراق هو البلد المرجعي بمسافة تساوي صفرًا. تُعرض جميع بلدان المقارنة المحمّلة. تأتي الخصائص من فترة 2003–2007."},"Weights:":{"ro":"Ponderi:","ar":"الأوزان:"},"how much each feature matters after the features are put on a common scale. Zero excludes that feature.":{"ro":"importanța fiecărei caracteristici după aducerea lor la o scară comună. Zero exclude acea caracteristică.","ar":"أهمية كل خاصية بعد وضع الخصائص على مقياس مشترك. الصفر يستبعد الخاصية."},"Income:":{"ro":"Venit:","ar":"الدخل:"},"log real GDP per person, which reduces the effect of very large income differences.":{"ro":"logaritmul PIB-ului real pe persoană, care reduce efectul diferențelor foarte mari de venit.","ar":"لوغاريتم الناتج المحلي الإجمالي الحقيقي للفرد، لتقليل أثر فروق الدخل الكبيرة جدًا."},"Distance:":{"ro":"Distanță:","ar":"المسافة:"},"a unitless similarity measure. A lower value means a closer match on the selected features.":{"ro":"o măsură de similaritate fără unitate. O valoare mai mică înseamnă o potrivire mai apropiată pe caracteristicile selectate.","ar":"مقياس تشابه بلا وحدة. تعني القيمة الأقل تشابهًا أكبر في الخصائص المختارة."},"The ranking describes similarity within this country set. It does not establish why economies developed differently.":{"ro":"Clasamentul descrie similaritatea în acest grup de țări. Nu stabilește de ce economiile s-au dezvoltat diferit.","ar":"يصف الترتيب التشابه ضمن هذه المجموعة من البلدان. ولا يحدد أسباب اختلاف تطور اقتصاداتها."},"Oil-rent weight":{"ro":"Ponderea rentelor petroliere","ar":"وزن الريع النفطي"},"Income weight":{"ro":"Ponderea venitului","ar":"وزن الدخل"},"Manufacturing weight":{"ro":"Ponderea industriei prelucrătoare","ar":"وزن الصناعة التحويلية"},"COUNTRY / REFERENCE":{"ro":"ȚARĂ / REPER","ar":"البلد / المرجع"},"DISTANCE · UNITLESS":{"ro":"DISTANȚĂ · FĂRĂ UNITATE","ar":"المسافة · بلا وحدة"},"A lower distance means a closer match on these features, among the countries I have loaded. This does not prove why their economies developed differently. I may add Bahrain after checking its data.":{"ro":"O distanță mai mică indică o potrivire mai apropiată pe aceste caracteristici, între țările încărcate. Nu demonstrează de ce economiile lor s-au dezvoltat diferit. Aș putea adăuga Bahrain după verificarea datelor sale.","ar":"تعني المسافة الأقل تشابهًا أكبر في هذه الخصائص بين البلدان المحمّلة. ولا تثبت سبب اختلاف تطور اقتصاداتها. قد أضيف البحرين بعد التحقق من بياناتها."},"Retry the preview ↻":{"ro":"Reîncearcă previzualizarea ↻","ar":"أعد تحميل المعاينة ↻"},"I use Python to check the inputs, prepare the observations and run the experiments. The interface helps me inspect the results and export their evidence.":{"ro":"Folosesc Python pentru a verifica datele de intrare, a pregăti observațiile și a rula experimentele. Interfața mă ajută să examinez rezultatele și să export dovezile lor.","ar":"أستخدم Python للتحقق من المدخلات وتجهيز المشاهدات وإجراء التجارب. تساعدني الواجهة على فحص النتائج وتصدير الأدلة المرتبطة بها."},"My Python project":{"ro":"Proiectul meu Python","ar":"مشروعي بلغة Python"},"Private repository · access required":{"ro":"Depozit privat · acces necesar","ar":"مستودع خاص · يلزم تصريح بالوصول"},"04 / REAL SOURCES AND CLEAR WINDOWS":{"ro":"04 / SURSE REALE ȘI PERIOADE CLARE","ar":"04 / مصادر موثقة وفترات واضحة"},"THE DATA COMES FIRST":{"ro":"DATELE VIN PRIMELE","ar":"البيانات أولًا"},"I start with":{"ro":"Încep cu","ar":"أبدأ بفهم"},"the":{"ro":"","ar":""},"new Iraq.":{"ro":"noul Irak.","ar":"العراق الجديد."},"2003 marks the US-led invasion and the fall of Saddam Hussein's regime. I chose this as the starting point for understanding Iraq's economy in the period that followed.":{"ro":"Anul 2003 marchează invazia condusă de SUA și căderea regimului lui Saddam Hussein. L-am ales ca punct de pornire pentru înțelegerea economiei Irakului în perioada care a urmat.","ar":"يمثل عام 2003 الغزو الذي قادته الولايات المتحدة وسقوط نظام صدام حسين. اخترته نقطة بداية لفهم اقتصاد العراق في الفترة التالية."},"01 / DEVELOPMENT":{"ro":"01 / DEZVOLTARE","ar":"01 / التنمية"},"Annual history":{"ro":"Istoric anual","ar":"السجل السنوي"},"Growth, real income per person and manufacturing run through 2025. Oil rents keep their available 2003–2021 window.":{"ro":"Creșterea, producția reală pe persoană și industria prelucrătoare acoperă perioada până în 2025. Rentele petroliere păstrează intervalul disponibil 2003–2021.","ar":"تمتد بيانات النمو والناتج الحقيقي للفرد والصناعة التحويلية حتى عام 2025. يحتفظ الريع النفطي بفترته المتاحة 2003–2021."},"World Bank WDI ↗":{"ro":"Indicatorii WDI ai Băncii Mondiale ↗","ar":"مؤشرات التنمية العالمية للبنك الدولي ↗"},"02 / GOVERNMENT ACCOUNTS":{"ro":"02 / CONTURI GUVERNAMENTALE","ar":"02 / الحسابات الحكومية"},"Monthly fiscal detail":{"ro":"Detalii fiscale lunare","ar":"التفاصيل المالية الشهرية"},"The continuous model uses 2016–June 2026. I preserve cumulative accounts, derive monthly increments and keep the earlier archive separate for review.":{"ro":"Modelul continuu folosește perioada 2016–iunie 2026. Păstrez conturile cumulative, calculez diferențele lunare și mențin separat arhiva anterioară pentru verificare.","ar":"يستخدم النموذج المتصل الفترة من 2016 إلى يونيو 2026. أحتفظ بالحسابات التراكمية وأستخرج الفروق الشهرية وأُبقي الأرشيف الأقدم منفصلًا للمراجعة."},"CBI statistical bulletins ↗":{"ro":"Buletinele statistice ale Băncii Centrale a Irakului ↗","ar":"النشرات الإحصائية للبنك المركزي العراقي ↗"},"03 / FUTURE SCENARIOS":{"ro":"03 / SCENARII VIITOARE","ar":"03 / السيناريوهات المستقبلية"},"A published annual outlook":{"ro":"Perspective anuale publicate","ar":"آفاق سنوية منشورة"},"The IMF April 2026 projections through 2031 provide a separate baseline for sensitivity calculations.":{"ro":"Proiecțiile FMI din aprilie 2026, până în 2031, oferă un scenariu de referință separat pentru calculele de sensibilitate.","ar":"توفر توقعات صندوق النقد الدولي الصادرة في أبريل 2026 حتى عام 2031 مسارًا مرجعيًا مستقلًا لحسابات الحساسية."},"IMF World Economic Outlook ↗":{"ro":"Perspectivele economice mondiale ale FMI ↗","ar":"آفاق الاقتصاد العالمي لصندوق النقد الدولي ↗"},"I keep each measurement at its original frequency. I do not repeat annual GDP twelve times to create monthly observations, and I do not treat a partial year as a completed year.":{"ro":"Păstrez fiecare măsură la frecvența sa originală. Nu repet PIB-ul anual de douăsprezece ori pentru a crea observații lunare și nu tratez un an parțial ca un an complet.","ar":"أحافظ على التواتر الأصلي لكل قياس. لا أكرر الناتج المحلي السنوي اثنتي عشرة مرة لإنشاء مشاهدات شهرية، ولا أتعامل مع السنة الجزئية على أنها سنة مكتملة."},"05 / WHAT I HAVE BUILT":{"ro":"05 / CE AM CONSTRUIT","ar":"05 / ما بنيته"},"A PROGRAM AND A RESEARCH PROCESS":{"ro":"UN PROGRAM ȘI UN PROCES DE CERCETARE","ar":"برنامج ومسار بحثي"},"The working Python application showing its 126-month fiscal dataset and the monthly revenue and spending chart":{"ro":"Aplicația Python funcțională cu setul fiscal de 126 de luni și graficul veniturilor și cheltuielilor lunare","ar":"تطبيق Python الذي يعمل، ويعرض بيانات مالية لـ126 شهرًا ورسم الإيرادات والنفقات الشهرية"},"My actual Streamlit prototype · captured October 2026":{"ro":"Prototipul meu real Streamlit · captură din octombrie 2026","ar":"نموذجي الأولي الفعلي باستخدام Streamlit · لقطة من أكتوبر 2026"},"More than":{"ro":"Mai mult decât","ar":"أكثر من"},"the final chart.":{"ro":"graficul final.","ar":"الرسم النهائي."},"I want to be able to follow a value from its source to the result on screen. That means preserving definitions, checking the calculations and making the analysis reproducible.":{"ro":"Vreau să pot urmări o valoare de la sursă până la rezultatul de pe ecran. Asta înseamnă păstrarea definițiilor, verificarea calculelor și o analiză care poate fi reprodusă.","ar":"أريد تتبع القيمة من مصدرها إلى النتيجة المعروضة. يتطلب ذلك الحفاظ على التعريفات والتحقق من الحسابات وجعل التحليل قابلًا لإعادة الإنتاج."},"A documented data pipeline":{"ro":"Un flux de date documentat","ar":"مسار بيانات موثق"},"Source snapshots, units, gaps, fingerprints and cumulative-to-monthly conversion.":{"ro":"Versiuni salvate ale surselor, unități, lipsuri, amprente digitale și conversie din valori cumulative în valori lunare.","ar":"نسخ محفوظة للمصادر ووحدات وفجوات وبصمات رقمية وتحويل القيم التراكمية إلى قيم شهرية."},"Explainable computations":{"ro":"Calcule explicabile","ar":"حسابات قابلة للتفسير"},"Country distances, chronological forecast tests, visible uncertainty and scenario assumptions.":{"ro":"Distanțe între țări, teste cronologice ale prognozelor, incertitudine vizibilă și ipoteze ale scenariilor.","ar":"مسافات بين البلدان واختبارات زمنية للتنبؤات وعدم يقين ظاهر وافتراضات السيناريوهات."},"A working interface":{"ro":"O interfață funcțională","ar":"واجهة تعمل"},"Controls, source-quality views and exportable results that I can demonstrate and improve.":{"ro":"Comenzi, vizualizări ale calității surselor și rezultate exportabile pe care le pot demonstra și îmbunătăți.","ar":"أدوات تحكم وعروض لجودة المصادر ونتائج قابلة للتصدير والعرض والتحسين."},"06 / LOOK THROUGH THE WORK":{"ro":"06 / DESCOPERĂ LUCRAREA","ar":"06 / تصفح المشروع"},"MY CURRENT MATERIALS":{"ro":"MATERIALELE MELE ACTUALE","ar":"موادي الحالية"},"The work is":{"ro":"Proiectul","ar":"المشروع"},"taking shape.":{"ro":"prinde contur.","ar":"يتبلور."},"01 / PRESENTATION":{"ro":"01 / PREZENTARE","ar":"01 / العرض"},"My thesis pitch":{"ro":"Prezentarea lucrării mele","ar":"عرض مشروع تخرجي"},"I will share the presentation pack when the project is finished.":{"ro":"Voi distribui pachetul de prezentare când proiectul va fi finalizat.","ar":"سأشارك حزمة العرض عندما يكتمل المشروع."},"DOWNLOAD COMING LATER":{"ro":"DESCĂRCARE DISPONIBILĂ ULTERIOR","ar":"التنزيل متاح لاحقًا"},"02 / RESEARCH":{"ro":"02 / CERCETARE","ar":"02 / البحث"},"The plan behind it":{"ro":"Planul din spatele proiectului","ar":"الخطة وراء المشروع"},"My question, data, proposed methods and the work I still need to complete.":{"ro":"Întrebarea mea, datele, metodele propuse și munca pe care mai trebuie să o închei.","ar":"سؤالي وبياناتي وأساليبي المقترحة والعمل الذي ما زلت بحاجة إلى إكماله."},"Read my research plan ↗":{"ro":"Citește planul meu de cercetare ↗","ar":"اقرأ خطة بحثي ↗"},"03 / PYTHON APPLICATION":{"ro":"03 / APLICAȚIE PYTHON","ar":"03 / تطبيق Python"},"The application I am building":{"ro":"Aplicația pe care o construiesc","ar":"التطبيق الذي أبنيه"},"My current Python program, data records, experiments and research notes in the project repository.":{"ro":"Programul meu Python actual, evidențele datelor, experimentele și notele de cercetare din depozitul proiectului.","ar":"برنامج Python الحالي وسجلات البيانات والتجارب والملاحظات البحثية في مستودع المشروع."},"Download the Python project from GitHub ↗":{"ro":"Descarcă proiectul Python de pe GitHub ↗","ar":"نزّل مشروع Python من GitHub ↗"},"The repository is private. GitHub sign-in and repository access are required.":{"ro":"Depozitul este privat. Sunt necesare autentificarea GitHub și accesul la depozit.","ar":"المستودع خاص. يلزم تسجيل الدخول إلى GitHub والحصول على صلاحية الوصول إليه."},"07 / KEEPING THE WORK MOVING":{"ro":"07 / CONTINUAREA PROIECTULUI","ar":"07 / مواصلة العمل"},"MY ROUTE TO July 2027":{"ro":"DRUMUL MEU SPRE IULIE 2027","ar":"طريقي إلى يوليو 2027"},"What I'm":{"ro":"La ce","ar":"ما"},"working on.":{"ro":"lucrez acum.","ar":"أعمل عليه."},"My coordinator and provisional title":{"ro":"Coordonatorul meu și titlul provizoriu","ar":"المشرف والعنوان الحالي"},"Professor Uscatu has agreed to coordinate my thesis. I have chosen a title that brings together my study of Iraq and the economic analysis system I want to keep developing. I will confirm the title and final scope with him.":{"ro":"Profesorul Uscatu a acceptat să îmi coordoneze lucrarea. Am ales un titlu care reunește studiul Irakului și sistemul de analiză economică pe care vreau să îl dezvolt în continuare. Voi confirma împreună cu el titlul și delimitarea finală.","ar":"وافق الأستاذ Uscatu على الإشراف على مشروع تخرجي. اخترت عنوانًا يجمع دراسة العراق ونظام التحليل الاقتصادي الذي أريد مواصلة تطويره. سأؤكد معه العنوان والنطاق النهائيين."},"A place to keep the work together":{"ro":"Un loc pentru întregul proiect","ar":"مكان يجمع العمل"},"I have organized the program, data, research and writing into one private repository, with this page as a way to share the project as it develops.":{"ro":"Am organizat programul, datele, cercetarea și redactarea într-un singur depozit privat. Această pagină îmi permite să prezint evoluția proiectului.","ar":"نظمت البرنامج والبيانات والبحث والكتابة في مستودع خاص واحد، وتتيح لي هذه الصفحة مشاركة المشروع أثناء تطوره."},"Moving the fiscal experiment to monthly data":{"ro":"Trecerea experimentului fiscal la date lunare","ar":"نقل التجربة المالية إلى البيانات الشهرية"},"After checking the archived CBI tables, I prepared a continuous 126-month fiscal core and tested five forecasting methods on 24 shared targets.":{"ro":"După verificarea tabelelor CBI arhivate, am pregătit un nucleu fiscal continuu de 126 de luni și am testat cinci metode de prognoză pe 24 de luni comune.","ar":"بعد التحقق من جداول البنك المركزي العراقي المؤرشفة، أعددت سلسلة مالية متصلة من 126 شهرًا واختبرت خمس طرق للتنبؤ على 24 شهرًا مشتركًا."},"Starting with evidence":{"ro":"Pornind de la dovezi","ar":"البداية بالأدلة"},"I checked the available datasets before choosing the direction, prepared the annual development history and started the first Python prototype.":{"ro":"Am verificat seturile de date disponibile înainte să aleg direcția, am pregătit istoricul anual al dezvoltării și am început primul prototip Python.","ar":"راجعت مجموعات البيانات المتاحة قبل اختيار الاتجاه، وجهزت السجل السنوي للتنمية وبدأت أول نموذج أولي بلغة Python."},"NEXT STEPS":{"ro":"PAȘII URMĂTORI","ar":"الخطوات التالية"},"There is still":{"ro":"Mai sunt","ar":"ما زال هناك"},"work to do.":{"ro":"lucruri de făcut.","ar":"عمل لإنجازه."},"Agree a focused thesis question and scope with my professors.":{"ro":"Să stabilesc cu profesorii o întrebare și o delimitare clară a lucrării.","ar":"الاتفاق مع أساتذتي على سؤال محدد ونطاق واضح لمشروع التخرج."},"Review the statistical diagnostics, source adjustments and final evaluation plan.":{"ro":"Să revizuiesc diagnosticele statistice, ajustările surselor și planul final de evaluare.","ar":"مراجعة الفحوص الإحصائية وتعديلات المصادر وخطة التقييم النهائية."},"Improve the fiscal database, experiment records and application performance.":{"ro":"Să îmbunătățesc baza de date fiscală, evidențele experimentelor și performanța aplicației.","ar":"تحسين قاعدة البيانات المالية وسجلات التجارب وأداء التطبيق."},"Investigate a comparable breakdown of executed spending where the data support it.":{"ro":"Să investighez o defalcare comparabilă a cheltuielilor executate, unde datele permit.","ar":"دراسة توزيع قابل للمقارنة للإنفاق المنفذ حيث تسمح البيانات."},"Write the thesis, evaluate the application and prepare my defence.":{"ro":"Să redactez lucrarea, să evaluez aplicația și să pregătesc susținerea.","ar":"كتابة البحث وتقييم التطبيق والتحضير للمناقشة."},"I will refine the question, methods and software contribution with my professors' advice.":{"ro":"Voi rafina întrebarea, metodele și contribuția software cu sfaturile profesorilor mei.","ar":"سأراجع السؤال والأساليب والإسهام البرمجي مستفيدًا من نصائح أساتذتي."},"WHERE I WANT TO TAKE IT":{"ro":"UNDE VREAU SĂ AJUNG","ar":"إلى أين أريد الوصول"},"I am starting with Iraq.":{"ro":"Încep cu Irakul.","ar":"أبدأ بالعراق."},"I want the program to go further.":{"ro":"Vreau ca programul să meargă mai departe.","ar":"وأريد للبرنامج أن يتوسع."},"Eventually, I want this program to be useful for any country, with a clear way to import different datasets. For now, I am building and testing it around the Iraqi data I understand and care about. Once that works well, I want to make the import process, country choices and analysis easier to adapt. Different datasets will still need their own checks and suitable methods; that wider version is something I want to develop after the core thesis.":{"ro":"În timp, vreau ca acest program să fie util pentru orice țară, cu o modalitate clară de a importa seturi de date diferite. Deocamdată îl construiesc și îl testez pe datele irakiene pe care le înțeleg și care contează pentru mine. După ce această parte funcționează bine, vreau să fac importul, alegerea țărilor și analiza mai ușor de adaptat. Fiecare set de date va avea în continuare nevoie de verificări proprii și metode potrivite; versiunea mai largă este un obiectiv pentru după nucleul lucrării de licență.","ar":"أريد في النهاية أن يكون هذا البرنامج مفيدًا لأي بلد، مع طريقة واضحة لاستيراد مجموعات بيانات مختلفة. أبنيه وأختبره الآن على البيانات العراقية التي أفهمها وأهتم بها. بعد أن يعمل ذلك جيدًا، أريد تسهيل تكييف الاستيراد واختيار البلدان والتحليل. ستظل كل مجموعة بيانات بحاجة إلى فحوصها وأساليبها المناسبة؛ وأريد تطوير هذه النسخة الأوسع بعد إكمال أساس مشروع التخرج."},"A boat and water buffalo in the Iraqi marshes, photographed by Taisir Mahdi":{"ro":"O barcă și bivoli de apă în mlaștinile irakiene, fotografiate de Taisir Mahdi","ar":"قارب وجواميس في الأهوار العراقية، بعدسة Taisir Mahdi"},"THE REASON I KEEP COMING BACK TO THIS":{"ro":"DE CE REVIN MEREU LA ACEST PROIECT","ar":"سبب عودتي إلى هذا المشروع"},"A place I know.":{"ro":"Un loc pe care îl cunosc.","ar":"مكان أعرفه."},"An economy I want":{"ro":"O economie pe care vreau","ar":"واقتصاد أريد"},"to understand.":{"ro":"să o înțeleg.","ar":"أن أفهمه."},"I want this project to help me ask better questions, become a better programmer and learn statistics I can keep building on.":{"ro":"Vreau ca acest proiect să mă ajute să pun întrebări mai bune, să devin un programator mai bun și să învăț statistică pe care pot continua să o dezvolt.","ar":"أريد أن يساعدني هذا المشروع على طرح أسئلة أفضل وتطوير مهاراتي البرمجية وتعلم إحصاء يمكنني البناء عليه."},"Talk to me about the project":{"ro":"Discută cu mine despre proiect","ar":"تحدث معي عن المشروع"},"NOORULDEEN AL SAMMARRAIE":{"ro":"NOORULDEEN AL SAMMARRAIE","ar":"نورالدين السامرائي"},"My thesis · work in progress":{"ro":"Lucrarea mea · în dezvoltare","ar":"مشروع تخرجي · قيد التطوير"},"Published 2026-10-13 · Monthly fiscal source window ends June 2026 · Source snapshots: 10 and 12 October 2026":{"ro":"Publicat la 2026-10-13 · Datele fiscale lunare se încheie în iunie 2026 · Surse salvate: 10 și 12 octombrie 2026","ar":"نُشر في 2026-10-13 · تنتهي بيانات المالية الشهرية في يونيو 2026 · نسخ المصادر: 10 و12 أكتوبر 2026"},"Sources and image credits":{"ro":"Surse și credite pentru imagini","ar":"المصادر وحقوق الصور"},"Development data: World Bank WDI, CC BY 4.0. Scenario baseline: IMF WEO, April 2026. Model results are my saved exploratory calculations using documented CBI accounts. Source snapshots remain labelled.":{"ro":"Date de dezvoltare: WDI, Banca Mondială, CC BY 4.0. Scenariu de referință: WEO, FMI, aprilie 2026. Rezultatele modelelor sunt calculele mele exploratorii salvate, folosind conturile CBI documentate. Versiunile surselor rămân etichetate.","ar":"بيانات التنمية: مؤشرات البنك الدولي، CC BY 4.0. المسار المرجعي: آفاق الاقتصاد العالمي لصندوق النقد الدولي، أبريل 2026. نتائج النماذج هي حساباتي الاستكشافية المحفوظة باستخدام حسابات موثقة للبنك المركزي العراقي. تبقى نسخ المصادر مؤرخة بوضوح."},"Historical starting point:":{"ro":"Punct de pornire istoric:","ar":"نقطة البداية التاريخية:"},"US Office of the Historian":{"ro":"Biroul Istoricului al SUA","ar":"مكتب المؤرخ الأمريكي"},"and":{"ro":"și","ar":"و"},"UN Secretary-General, December 2003":{"ro":"Secretarul General al ONU, decembrie 2003","ar":"الأمين العام للأمم المتحدة، ديسمبر 2003"},". My chosen period does not by itself establish the causes of later economic outcomes.":{"ro":". Perioada aleasă nu stabilește singură cauzele rezultatelor economice ulterioare.","ar":". لا تحدد الفترة التي اخترتها وحدها أسباب النتائج الاقتصادية اللاحقة."},"My Iraq illustration is a decorative drawing, not a data chart. Samarra:":{"ro":"Ilustrația Irakului este un desen decorativ, nu un grafic de date. Samarra:","ar":"رسم العراق توضيح زخرفي وليس رسمًا بيانيًا للبيانات. سامراء:"},"David Stanley":{"ro":"David Stanley","ar":"David Stanley"},"CC BY 2.0":{"ro":"CC BY 2.0","ar":"CC BY 2.0"},". Iraqi marshes:":{"ro":". Mlaștinile irakiene:","ar":". الأهوار العراقية:"},"Taisir Mahdi":{"ro":"Taisir Mahdi","ar":"Taisir Mahdi"},"CC BY-SA 4.0":{"ro":"CC BY-SA 4.0","ar":"CC BY-SA 4.0"},". Photos are displayed with proportional crops; original pixels are preserved.":{"ro":". Fotografiile sunt afișate cu decupaje proporționale; pixelii originali sunt păstrați.","ar":". تُعرض الصور بقص متناسب مع الحفاظ على البكسلات الأصلية."},"My thesis question, data, methods and next steps for the Iraq Economic Observatory.":{"ro":"Întrebarea, datele, metodele și pașii următori ai lucrării mele despre Observatorul Economic al Irakului.","ar":"سؤال مشروع تخرجي وبياناته وأساليبه وخطواته القادمة في المرصد الاقتصادي العراقي."},"My thesis research plan | Nooruldeen":{"ro":"Planul lucrării mele de licență | Nooruldeen","ar":"خطة بحث مشروع تخرجي | نورالدين"},"Skip to the research plan":{"ro":"Sari la planul de cercetare","ar":"انتقل إلى خطة البحث"},"Back to my project ↗":{"ro":"Înapoi la proiectul meu ↗","ar":"العودة إلى مشروعي ↗"},"MY THESIS / RESEARCH PLAN":{"ro":"LUCRAREA MEA / PLAN DE CERCETARE","ar":"مشروع تخرجي / خطة البحث"},"ON THIS PAGE":{"ro":"PE ACEASTĂ PAGINĂ","ar":"في هذه الصفحة"},"Research plan sections":{"ro":"Secțiunile planului de cercetare","ar":"أقسام خطة البحث"},"The questions behind the project":{"ro":"Întrebările din spatele proiectului","ar":"الأسئلة وراء المشروع"},"Why I start with Iraq after 2003":{"ro":"De ce încep cu Irakul de după 2003","ar":"لماذا أبدأ بالعراق بعد عام 2003"},"How I prepare the monthly figures":{"ro":"Cum pregătesc valorile lunare","ar":"كيف أجهز الأرقام الشهرية"},"What I have tested so far":{"ro":"Ce am testat până acum","ar":"ما اختبرته حتى الآن"},"What the budget scenarios mean":{"ro":"Ce înseamnă scenariile bugetare","ar":"ماذا تعني سيناريوهات الموازنة"},"What the application does":{"ro":"Ce face aplicația","ar":"ما يقدمه التطبيق"},"Where I want to take the program":{"ro":"Unde vreau să duc programul","ar":"إلى أين أريد تطوير البرنامج"},"Why I would value my professors' guidance":{"ro":"De ce apreciez îndrumarea profesorilor","ar":"لماذا أقدّر توجيه أساتذتي"},"What I want to improve next":{"ro":"Ce vreau să îmbunătățesc în continuare","ar":"ما أريد تحسينه لاحقًا"},"Where the evidence comes from":{"ro":"De unde provin dovezile","ar":"مصادر الأدلة"},"What I want to build and understand":{"ro":"Ce vreau să construiesc și să înțeleg","ar":"ما أريد بناءه وفهمه"},"I grew up in Iraq, and I have always wanted to understand its economy better. Iraq has valuable oil resources, but having those resources has not made development straightforward. I want to look at the numbers, understand what they can tell me, and build a Python application that helps me explore the questions properly.":{"ro":"Am crescut în Irak și mi-am dorit mereu să îi înțeleg mai bine economia. Irakul are resurse petroliere valoroase, dar acestea nu au făcut dezvoltarea simplă. Vreau să examinez cifrele, să înțeleg ce îmi pot spune și să construiesc o aplicație Python care mă ajută să explorez corect întrebările.","ar":"نشأت في العراق، وطالما أردت فهم اقتصاده بشكل أفضل. يمتلك العراق موارد نفطية قيّمة، لكنها لم تجعل التنمية بسيطة. أريد قراءة الأرقام وفهم ما يمكن أن تخبرني به وبناء تطبيق Python يساعدني على استكشاف الأسئلة بطريقة سليمة."},"My provisional thesis title is":{"ro":"Titlul meu provizoriu este","ar":"عنوان مشروع تخرجي الحالي هو"},". I have chosen this title for now and will confirm it with Professor Uscatu before treating it as official. I am studying Economic Informatics at ASE Bucharest, and I plan to defend in July 2027.":{"ro":". Am ales acest titlu pentru moment și îl voi confirma cu profesorul Uscatu înainte să îl consider oficial. Studiez Informatică Economică la ASE București și îmi propun să susțin lucrarea în iulie 2027.","ar":". اخترت هذا العنوان حاليًا وسأؤكده مع الأستاذ Uscatu قبل اعتباره رسميًا. أدرس المعلوماتية الاقتصادية في أكاديمية بوخارست للدراسات الاقتصادية، وأخطط للمناقشة في يوليو 2027."},"Professor Uscatu has agreed to coordinate my thesis. I will discuss the final question and scope with him. Iraq gives the study its personal purpose, while the analysis system is something I want to develop further and eventually adapt to other countries and suitable datasets.":{"ro":"Profesorul Uscatu a acceptat să îmi coordoneze lucrarea. Voi discuta cu el întrebarea și delimitarea finală. Irakul dă studiului sensul personal, iar sistemul de analiză este un proiect pe care vreau să îl dezvolt în continuare și, în timp, să îl adaptez altor țări și seturi de date potrivite.","ar":"وافق الأستاذ Uscatu على الإشراف على مشروع تخرجي. سأناقش معه السؤال والنطاق النهائيين. يمنح العراق الدراسة معناها الشخصي، بينما أريد مواصلة تطوير نظام التحليل وتكييفه لاحقًا لبلدان أخرى ومجموعات بيانات مناسبة."},"How has Iraq's economy changed since 2003? How much does the government rely on oil-related income? What happens when revenue falls but spending does not fall with it? Can monthly data help me make useful short-term forecasts?":{"ro":"Cum s-a schimbat economia Irakului din 2003? Cât de mult depinde guvernul de veniturile legate de petrol? Ce se întâmplă când veniturile scad, dar cheltuielile nu scad odată cu ele? Pot datele lunare să mă ajute să fac prognoze utile pe termen scurt?","ar":"كيف تغير اقتصاد العراق منذ عام 2003؟ إلى أي مدى تعتمد الحكومة على الدخل المرتبط بالنفط؟ ماذا يحدث عندما تنخفض الإيرادات ولا تنخفض معها النفقات؟ هل تساعدني البيانات الشهرية على إعداد تنبؤات مفيدة على المدى القصير؟"},"I also want to understand why Iraq's development has followed a different path from countries such as the UAE and Saudi Arabia. Where did public spending go, and how much helped build a more diverse economy? These are questions I want to investigate. A few charts or a country ranking cannot answer them on their own.":{"ro":"Vreau să înțeleg și de ce dezvoltarea Irakului a urmat un alt drum decât în țări precum Emiratele Arabe Unite și Arabia Saudită. Unde s-au dus cheltuielile publice și cât au ajutat la construirea unei economii mai diversificate? Sunt întrebări de investigat. Câteva grafice sau un clasament al țărilor nu le pot răspunde singure.","ar":"أريد أيضًا فهم سبب اختلاف مسار التنمية في العراق عن بلدان مثل الإمارات العربية المتحدة والسعودية. أين ذهب الإنفاق العام، وكم ساهم في بناء اقتصاد أكثر تنوعًا؟ هذه أسئلة أريد دراستها. لا تستطيع بعض الرسوم أو ترتيب البلدان الإجابة عنها بمفردها."},"I do not want to begin with a conclusion and then find numbers to support it. For example, Iraq's budget has not been in deficit every year. I need to check what happened, when it happened, and what the available evidence actually supports.":{"ro":"Nu vreau să pornesc de la o concluzie și apoi să caut cifre care să o susțină. De exemplu, bugetul Irakului nu a fost în deficit în fiecare an. Trebuie să verific ce s-a întâmplat, când și ce susțin de fapt dovezile disponibile.","ar":"لا أريد البدء باستنتاج ثم البحث عن أرقام تدعمه. فمثلًا، لم تكن موازنة العراق في عجز كل عام. أحتاج إلى التحقق مما حدث ومتى حدث وما تدعمه الأدلة المتاحة فعلًا."},"I chose 2003 because it marks the US-led invasion and the fall of Saddam Hussein's regime. I want to understand the economy in the period that followed, without assuming that one event explains every later outcome.":{"ro":"Am ales anul 2003 deoarece marchează invazia condusă de SUA și căderea regimului lui Saddam Hussein. Vreau să înțeleg economia în perioada următoare, fără să presupun că un singur eveniment explică toate rezultatele ulterioare.","ar":"اخترت عام 2003 لأنه يمثل الغزو الذي قادته الولايات المتحدة وسقوط نظام صدام حسين. أريد فهم الاقتصاد في الفترة التالية دون افتراض أن حدثًا واحدًا يفسر جميع النتائج اللاحقة."},"I use two parts of the data together. The yearly data gives me the longer development picture from 2003. The monthly government accounts let me look more closely at revenue, spending and short-term changes.":{"ro":"Folosesc împreună două părți ale datelor. Datele anuale oferă imaginea dezvoltării pe termen lung din 2003. Conturile guvernamentale lunare îmi permit să examinez mai atent veniturile, cheltuielile și schimbările pe termen scurt.","ar":"أستخدم جزأين من البيانات معًا. تمنحني البيانات السنوية صورة التنمية الأطول منذ عام 2003، وتتيح الحسابات الحكومية الشهرية فحص الإيرادات والنفقات والتغيرات القصيرة الأجل بتفصيل أكبر."},"The yearly figures for growth, real GDP per person and manufacturing run through 2025. Real GDP per person is a measure of economic output per person, adjusted for price changes. It is not the same as the income of a typical household. The oil-rent figures are available through 2021. They estimate the value of oil production after production costs; they are not government oil revenue.":{"ro":"Valorile anuale pentru creștere, PIB real pe persoană și industria prelucrătoare merg până în 2025. PIB-ul real pe persoană măsoară producția economică pe persoană, ajustată pentru schimbările de preț. Nu este venitul unei gospodării obișnuite. Datele privind rentele petroliere sunt disponibile până în 2021. Ele estimează valoarea producției petroliere după costurile de producție; nu sunt veniturile petroliere ale guvernului.","ar":"تمتد الأرقام السنوية للنمو والناتج المحلي الإجمالي الحقيقي للفرد والصناعة التحويلية حتى عام 2025. يقيس الناتج الحقيقي للفرد الإنتاج الاقتصادي للفرد بعد تعديل تغيرات الأسعار، وليس دخل الأسرة المعتادة. تتوفر بيانات الريع النفطي حتى عام 2021، وتقدر قيمة إنتاج النفط بعد تكاليف الإنتاج؛ ولا تمثل الإيرادات النفطية الحكومية."},"My consistent monthly forecasting dataset runs from January 2016 to June 2026: 126 months. I also have an earlier archive starting in 2008, but some years have changes in coverage or accounting adjustments that need more checking. That is why I am keeping the reliable modelling window separate for now.":{"ro":"Setul meu lunar consecvent pentru prognoză acoperă ianuarie 2016–iunie 2026: 126 de luni. Am și o arhivă mai veche, din 2008, dar unele perioade prezintă schimbări de acoperire sau ajustări contabile care trebuie verificate. De aceea păstrez deocamdată separat intervalul fiabil pentru modelare.","ar":"تغطي مجموعة التنبؤ الشهرية المتسقة يناير 2016–يونيو 2026، أي 126 شهرًا. لدي أيضًا أرشيف أقدم يبدأ في 2008، لكن بعض السنوات تتضمن تغيرات في التغطية أو تعديلات محاسبية تحتاج إلى مزيد من الفحص. لذلك أُبقي فترة النمذجة الموثوقة منفصلة حاليًا."},"Both frequencies can belong in the same thesis. I keep yearly figures yearly and monthly figures monthly. I do not turn one annual GDP value into twelve observations. I also keep January–June 2026 separate from a complete year.":{"ro":"Ambele frecvențe pot fi folosite în aceeași lucrare. Păstrez datele anuale anuale și pe cele lunare lunare. Nu transform o valoare anuală a PIB-ului în douăsprezece observații. Păstrez separat și ianuarie–iunie 2026 față de un an complet.","ar":"يمكن استخدام التواترين في مشروع واحد. أُبقي الأرقام السنوية سنوية والشهرية شهرية. لا أحول قيمة سنوية واحدة للناتج المحلي إلى اثنتي عشرة مشاهدة. وأميز كذلك يناير–يونيو 2026 عن سنة مكتملة."},"The Central Bank of Iraq tables report running totals within each year. A February value includes January and February together. To get February's own amount, I subtract January's total. For March, I subtract February's total, and so on. January starts a new year, so it uses its own reported amount.":{"ro":"Tabelele Băncii Centrale a Irakului raportează totaluri cumulative în fiecare an. Valoarea din februarie include ianuarie și februarie împreună. Pentru suma proprie lunii februarie scad totalul din ianuarie. Pentru martie scad totalul din februarie, și așa mai departe. Ianuarie începe un an nou, deci folosește suma sa raportată.","ar":"تُبلغ جداول البنك المركزي العراقي عن مجاميع تراكمية داخل كل سنة. تشمل قيمة فبراير شهري يناير وفبراير معًا. للحصول على مبلغ فبراير وحده، أطرح مجموع يناير. وفي مارس أطرح مجموع فبراير، وهكذا. يبدأ يناير سنة جديدة، لذلك تُستخدم قيمته المعلنة مباشرة."},"My code checks that these monthly amounts add back to the yearly total and that revenue minus spending equals the balance. It keeps the original values, source links, units and warnings so that I can trace a result back to its source.":{"ro":"Codul verifică dacă sumele lunare reconstruiesc totalul anual și dacă veniturile minus cheltuielile sunt egale cu soldul. Păstrează valorile originale, linkurile surselor, unitățile și avertismentele, astfel încât pot urmări un rezultat până la sursă.","ar":"يتحقق الكود من أن جمع المبالغ الشهرية يعيد المجموع السنوي، وأن الإيرادات ناقص النفقات تساوي الرصيد. ويحفظ القيم الأصلية وروابط المصادر والوحدات والتنبيهات لتتبع النتيجة إلى مصدرها."},"Some differences can reflect a correction to the accounts. I keep those visible. For example, one oil-and-mineral revenue difference in October 2019 is negative. I need to understand the accounting issue before treating it as ordinary economic behaviour.":{"ro":"Unele diferențe pot reflecta corecții ale conturilor. Le păstrez vizibile. De exemplu, o diferență a veniturilor din petrol și minerale în octombrie 2019 este negativă. Trebuie să înțeleg problema contabilă înainte să o tratez ca pe un comportament economic obișnuit.","ar":"قد تعكس بعض الفروق تصحيحًا للحسابات، وأُبقيها ظاهرة. مثلًا، أحد فروق إيرادات النفط والمعادن في أكتوبر 2019 سالب. أحتاج إلى فهم المشكلة المحاسبية قبل التعامل معها كسلوك اقتصادي عادي."},"My first forecasting experiment asks a focused question: can a model predict next month's reported government revenue better than a simple guess?":{"ro":"Primul experiment de prognoză pune o întrebare precisă: poate un model să anticipeze veniturile guvernamentale raportate pentru luna următoare mai bine decât o estimare simplă?","ar":"تطرح تجربتي الأولى للتنبؤ سؤالًا محددًا: هل يستطيع النموذج توقع الإيرادات الحكومية المعلنة للشهر التالي أفضل من تقدير بسيط؟"},"I start with two simple comparisons: use last month's revenue, or use revenue from the same month a year earlier. I then test AR(1), ARIMA and seasonal ARIMA. AR(1) uses the previous month's level; ARIMA can model changes and patterns in forecast errors; seasonal ARIMA also includes a yearly pattern in the monthly series. These are fixed starting models, not a final choice.":{"ro":"Încep cu două repere simple: veniturile lunii precedente sau cele din aceeași lună a anului anterior. Apoi testez AR(1), ARIMA și ARIMA sezonier. AR(1) folosește nivelul lunii precedente; ARIMA poate modela variații și tipare ale erorilor; ARIMA sezonier include și un tipar anual în seria lunară. Acestea sunt modele inițiale fixe, nu alegerea finală.","ar":"أبدأ بمرجعين بسيطين: إيرادات الشهر السابق أو إيرادات الشهر نفسه من السنة الماضية. ثم أختبر AR(1) وARIMA وARIMA الموسمي. يستخدم AR(1) مستوى الشهر السابق؛ ويمكن لـARIMA نمذجة التغيرات وأنماط أخطاء التنبؤ؛ ويضيف ARIMA الموسمي نمطًا سنويًا إلى السلسلة الشهرية. هذه نماذج أولية ثابتة وليست اختيارًا نهائيًا."},"All five methods predict the same 24 months, from July 2024 to June 2026. For each prediction, the model only gets the earlier fiscal observations. I start with 102 training months. The data comes from the saved, revised source tables, so this is a historical test rather than a reconstruction of exactly what someone knew at each publication date.":{"ro":"Toate cele cinci metode prognozează aceleași 24 de luni, iulie 2024–iunie 2026. Pentru fiecare prognoză, modelul primește doar observațiile fiscale anterioare. Încep cu 102 luni de antrenare. Datele provin din tabelele salvate și revizuite, deci acesta este un test istoric, nu o reconstrucție exactă a informațiilor cunoscute la fiecare dată de publicare.","ar":"تتنبأ الطرق الخمس بالأشهر الـ24 نفسها، من يوليو 2024 إلى يونيو 2026. يحصل النموذج في كل تنبؤ على المشاهدات المالية السابقة فقط. أبدأ بـ102 شهرًا للتدريب. تأتي البيانات من جداول محفوظة ومراجعة، لذا فهذا اختبار تاريخي وليس إعادة بناء دقيقة لما كان معروفًا في كل تاريخ نشر."},"I compare how far each prediction was from the reported result.":{"ro":"Compar distanța dintre fiecare prognoză și rezultatul raportat.","ar":"أقارن مقدار الفرق بين كل تنبؤ والنتيجة المعلنة."},"is the average size of the errors.":{"ro":"reprezintă mărimea medie a erorilor.","ar":"هو متوسط حجم الأخطاء."},"gives larger mistakes more weight. In this first test, AR(1) has the lowest MAE and ARIMA has the lowest RMSE. The seasonal model performs worse. A more complicated model has not automatically helped.":{"ro":"acordă greșelilor mari o pondere mai mare. În acest prim test, AR(1) are cel mai mic MAE, iar ARIMA cel mai mic RMSE. Modelul sezonier are rezultate mai slabe. Un model mai complex nu a ajutat automat.","ar":"يعطي الأخطاء الكبيرة وزنًا أكبر. في هذا الاختبار الأول، يحقق AR(1) أقل MAE ويحقق ARIMA أقل RMSE. أداء النموذج الموسمي أضعف. لم يؤدِ التعقيد الأكبر تلقائيًا إلى تحسن."},"I have not chosen the final model. I still need to check the remaining patterns in its errors, unusual months and changes in the series. The shaded 95% prediction band shows uncertainty under the model's assumptions. It is not a guarantee. The saved July–September 2026 predictions use data ending in June; they are not a fresh forecast made today.":{"ro":"Nu am ales modelul final. Mai trebuie să verific tiparele rămase în erori, lunile neobișnuite și schimbările din serie. Banda de predicție de 95% arată incertitudinea în condițiile ipotezelor modelului. Nu este o garanție. Prognozele salvate pentru iulie–septembrie 2026 folosesc date până în iunie; nu sunt prognoze noi făcute astăzi.","ar":"لم أختر النموذج النهائي. ما زلت بحاجة إلى فحص الأنماط المتبقية في الأخطاء والأشهر غير المعتادة وتغيرات السلسلة. يعرض شريط التنبؤ بنسبة 95% عدم اليقين وفق افتراضات النموذج، وليس ضمانًا. تستخدم تنبؤات يوليو–سبتمبر 2026 المحفوظة بيانات تنتهي في يونيو؛ وليست تنبؤات جديدة أُعدت اليوم."},"I use the IMF's April 2026 projections through 2031 as a separate yearly starting point. The application lets me change an assumption, such as a 10% fall in oil prices, and calculate how the budget balance changes.":{"ro":"Folosesc proiecțiile FMI din aprilie 2026, până în 2031, ca punct de pornire anual separat. Aplicația îmi permite să schimb o ipoteză, cum ar fi scăderea cu 10% a prețului petrolului, și să calculez modificarea soldului bugetar.","ar":"أستخدم توقعات صندوق النقد الدولي الصادرة في أبريل 2026 حتى عام 2031 كنقطة بداية سنوية مستقلة. يتيح لي التطبيق تغيير افتراض، مثل انخفاض سعر النفط بنسبة 10%، وحساب تغير رصيد الموازنة."},"This asks":{"ro":"Acest calcul întreabă","ar":"يسأل هذا الحساب"},"what would happen under these assumptions":{"ro":"ce s-ar întâmpla în aceste condiții","ar":"ما الذي سيحدث وفق هذه الافتراضات"},", rather than saying what will happen. In the simple price scenario, I keep spending, export quantities, other revenue, GDP and the exchange rate fixed. I choose how much revenue is assumed to respond to the price change. That share is visible and adjustable.":{"ro":", fără să afirme ce se va întâmpla. În scenariul simplu de preț păstrez fixe cheltuielile, cantitățile exportate, alte venituri, PIB-ul și cursul de schimb. Aleg cât din venituri se presupune că reacționează la preț. Ponderea este vizibilă și ajustabilă.","ar":"، دون الجزم بما سيحدث. في سيناريو السعر البسيط، أُبقي النفقات وكميات التصدير والإيرادات الأخرى والناتج المحلي الإجمالي وسعر الصرف ثابتة. أختار مقدار الإيرادات المفترض استجابتها لتغير السعر، وهذه الحصة ظاهرة وقابلة للتعديل."},"The result helps me see how sensitive the budget is to the assumptions. It does not include every government response or economic effect, and it does not assign a probability to the scenario.":{"ro":"Rezultatul mă ajută să văd sensibilitatea bugetului la ipoteze. Nu include toate reacțiile guvernului sau efectele economice și nu atribuie o probabilitate scenariului.","ar":"تساعدني النتيجة على رؤية حساسية الموازنة للافتراضات. لا تشمل كل الاستجابات الحكومية أو الآثار الاقتصادية، ولا تعطي احتمالًا للسيناريو."},"My Python application brings the sources, calculations and results together. I can explore the yearly history, inspect monthly accounts, compare forecast errors, see prediction uncertainty and export results. I can also compare countries using oil rents, real output per person and manufacturing, then change how much weight each feature gets.":{"ro":"Aplicația mea Python reunește sursele, calculele și rezultatele. Pot explora istoricul anual, inspecta conturile lunare, compara erorile prognozelor, vedea incertitudinea și exporta rezultatele. Pot și compara țările pe baza rentelor petroliere, producției reale pe persoană și industriei prelucrătoare, apoi schimba ponderea fiecărei caracteristici.","ar":"يجمع تطبيق Python المصادر والحسابات والنتائج. أستطيع استكشاف السجل السنوي وفحص الحسابات الشهرية ومقارنة أخطاء التنبؤ ورؤية عدم اليقين وتصدير النتائج. كما أستطيع مقارنة البلدان وفق الريع النفطي والناتج الحقيقي للفرد والصناعة التحويلية، ثم تغيير وزن كل خاصية."},"Those country comparisons show measured similarity within my selected set. They do not prove why one country developed differently from another. I want to use them as a starting point for better questions and a closer reading of the evidence.":{"ro":"Comparațiile arată similaritatea măsurată în grupul ales. Nu demonstrează de ce o țară s-a dezvoltat diferit de alta. Vreau să le folosesc ca punct de pornire pentru întrebări mai bune și o citire mai atentă a dovezilor.","ar":"توضح مقارنات البلدان التشابه المقاس ضمن المجموعة المختارة. ولا تثبت سبب اختلاف تطور بلد عن آخر. أريد استخدامها بداية لأسئلة أفضل وقراءة أعمق للأدلة."},"The website has a lighter browser preview of the saved results. It can redraw the charts, change comparison weights and recalculate the budget scenario. It does not run new Python model fits. The complete Streamlit application and its code stay in my private GitHub repository while I develop the project.":{"ro":"Site-ul are o previzualizare mai ușoară, în browser, a rezultatelor salvate. Poate redesena graficele, schimba ponderile de comparație și recalcula scenariul bugetar. Nu estimează noi modele Python. Aplicația completă Streamlit și codul său rămân în depozitul meu GitHub privat în timpul dezvoltării.","ar":"يقدم الموقع معاينة أخف للنتائج المحفوظة في المتصفح. يمكنها إعادة رسم المخططات وتغيير أوزان المقارنة وإعادة حساب سيناريو الموازنة. ولا تُجري ملاءمة جديدة لنماذج Python. يبقى تطبيق Streamlit الكامل وكوده في مستودع GitHub الخاص أثناء تطوير المشروع."},"I am keeping that broader aim separate from the minimum thesis. First, I need a reliable application for the questions and data I have already checked.":{"ro":"Păstrez acest obiectiv mai larg separat de nucleul lucrării. Mai întâi am nevoie de o aplicație fiabilă pentru întrebările și datele deja verificate.","ar":"أفصل هذا الطموح الأوسع عن الحد الأساسي لمشروع التخرج. أحتاج أولًا إلى تطبيق موثوق للأسئلة والبيانات التي تحققت منها."},"Professor Uscatu has agreed to coordinate my thesis. I would like his guidance on turning this into a well-designed Economic Informatics project: clear modules, sensible storage, reliable algorithms and an application that runs smoothly. I also want to understand the code well enough to explain and defend it myself.":{"ro":"Profesorul Uscatu a acceptat să îmi coordoneze lucrarea. Îmi doresc îndrumarea lui pentru un proiect de Informatică Economică bine conceput: module clare, stocare potrivită, algoritmi fiabili și o aplicație care funcționează fluent. Vreau și să înțeleg codul suficient pentru a-l explica și susține singur.","ar":"وافق الأستاذ Uscatu على الإشراف على مشروع تخرجي. أريد توجيهه لبناء مشروع جيد في المعلوماتية الاقتصادية، بوحدات واضحة وتخزين مناسب وخوارزميات موثوقة وتطبيق يعمل بسلاسة. وأريد فهم الكود بما يكفي لشرحه ومناقشته بنفسي."},"I would value Professor Davidescu's advice on what the data means, which statistical methods make sense and how to read the results without claiming more than they show. I especially want help reviewing the monthly models and their assumptions.":{"ro":"Aș aprecia sfaturile profesoarei Davidescu despre sensul datelor, metodele statistice potrivite și interpretarea rezultatelor fără afirmații care depășesc dovezile. Îmi doresc în special ajutor la revizuirea modelelor lunare și a ipotezelor lor.","ar":"سأقدّر نصائح الأستاذة Davidescu حول معنى البيانات والأساليب الإحصائية المناسبة وقراءة النتائج دون ادعاء أكثر مما تدعمه. وأرغب خصوصًا في مساعدة لمراجعة النماذج الشهرية وافتراضاتها."},"I will agree the final title and scope with Professor Uscatu. I will also discuss whether Professor Davidescu can offer methodological advice; her involvement is still subject to her agreement.":{"ro":"Voi stabili titlul și delimitarea finală cu profesorul Uscatu. Voi discuta și dacă profesoara Davidescu poate oferi sfaturi metodologice; implicarea ei depinde încă de acordul său.","ar":"سأتفق مع الأستاذ Uscatu على العنوان والنطاق النهائيين. وسأناقش أيضًا إمكانية تقديم الأستاذة Davidescu إرشادًا منهجيًا؛ وما زالت مشاركتها رهن موافقتها."},"The Python prototype currently passes 33 checks. I have enough verified data to build the core thesis: a checked data-processing system, monthly analysis and forecast comparison, yearly development context, clear scenarios and a working application.":{"ro":"Prototipul Python trece în prezent 33 de verificări. Am suficiente date verificate pentru nucleul lucrării: un sistem verificat de procesare a datelor, analiză lunară și comparație a prognozelor, context anual al dezvoltării, scenarii clare și o aplicație funcțională.","ar":"يجتاز نموذج Python الأولي حاليًا 33 فحصًا. لدي بيانات موثقة كافية لبناء أساس مشروع التخرج: نظام معالجة بيانات مُراجع، وتحليل شهري ومقارنة تنبؤات، وسياق سنوي للتنمية، وسيناريوهات واضحة، وتطبيق يعمل."},"Next, I want to review the data warnings and model checks, improve the database and application, and investigate spending categories where comparable records are available. I will keep the project focused enough to finish and understand it properly. A deeper explanation of development differences is something I can expand as the evidence and my professors' advice allow.":{"ro":"În continuare vreau să revizuiesc avertismentele privind datele și verificările modelelor, să îmbunătățesc baza de date și aplicația și să investighez categoriile de cheltuieli pentru care există evidențe comparabile. Voi păstra proiectul suficient de concentrat pentru a-l finaliza și înțelege bine. Pot extinde explicația diferențelor de dezvoltare pe măsură ce dovezile și sfaturile profesorilor permit.","ar":"أريد بعد ذلك مراجعة تنبيهات البيانات وفحوص النماذج وتحسين قاعدة البيانات والتطبيق ودراسة فئات الإنفاق التي تتوفر لها سجلات قابلة للمقارنة. سأحافظ على نطاق محدد يسمح بإكمال المشروع وفهمه جيدًا. ويمكنني توسيع تفسير اختلافات التنمية حين تسمح الأدلة ونصائح أساتذتي."},"My annual development data comes from":{"ro":"Datele mele anuale de dezvoltare provin din","ar":"تأتي بيانات التنمية السنوية من"},"World Bank World Development Indicators":{"ro":"Indicatorii de dezvoltare mondială ai Băncii Mondiale","ar":"مؤشرات التنمية العالمية للبنك الدولي"},". My monthly government accounts come from":{"ro":". Conturile guvernamentale lunare provin din","ar":". وتأتي الحسابات الحكومية الشهرية من"},"Central Bank of Iraq statistical bulletins":{"ro":"Buletinele statistice ale Băncii Centrale a Irakului","ar":"النشرات الإحصائية للبنك المركزي العراقي"},". My yearly outlook comes from the":{"ro":". Perspectivele anuale provin din","ar":". وتأتي الآفاق السنوية من"},"IMF World Economic Outlook":{"ro":"Perspectivele economice mondiale ale FMI","ar":"آفاق الاقتصاد العالمي لصندوق النقد الدولي"},", April 2026 edition. Exact file links, pages, units and source checks are kept in the project's data inventory.":{"ro":", ediția din aprilie 2026. Linkurile exacte ale fișierelor, paginile, unitățile și verificările surselor sunt păstrate în inventarul de date al proiectului.","ar":"، إصدار أبريل 2026. تُحفظ روابط الملفات الدقيقة والصفحات والوحدات وفحوص المصادر في جرد بيانات المشروع."},"For forecasting, I am using":{"ro":"Pentru prognoză folosesc","ar":"أستخدم للتنبؤ"},"Forecasting: Principles and Practice":{"ro":"Forecasting: Principles and Practice","ar":"Forecasting: Principles and Practice"},"and the":{"ro":"și","ar":"و"},"official statsmodels documentation":{"ro":"documentația oficială statsmodels","ar":"الوثائق الرسمية لـstatsmodels"},". The more detailed method notes remain in my private research folder.":{"ro":". Notele metodologice mai detaliate rămân în dosarul meu privat de cercetare.","ar":". تبقى الملاحظات المنهجية الأكثر تفصيلًا في مجلد البحث الخاص."},"For the 2003 starting point, I checked the":{"ro":"Pentru punctul de pornire din 2003 am consultat","ar":"راجعت لنقطة البداية عام 2003"},"UN Secretary-General’s December 2003 remarks":{"ro":"Declarațiile Secretarului General al ONU din decembrie 2003","ar":"تصريحات الأمين العام للأمم المتحدة في ديسمبر 2003"},"My research plan remains open to refinement with my professors.":{"ro":"Planul meu de cercetare rămâne deschis rafinării împreună cu profesorii.","ar":"تبقى خطة بحثي قابلة للمراجعة بالتعاون مع أساتذتي."},"No observations are available in this saved window.":{"ro":"Nu există observații în această perioadă salvată.","ar":"لا توجد مشاهدات متاحة في هذه الفترة المحفوظة."},"Saved research chart":{"ro":"Grafic al rezultatelor salvate","ar":"رسم للبحث المحفوظ"},"Month":{"ro":"Lună","ar":"الشهر"},"Year":{"ro":"An","ar":"السنة"},"Value":{"ro":"Valoare","ar":"القيمة"},"Period":{"ro":"Perioadă","ar":"الفترة"},"Horizontal axis: {period}. Vertical axis: {unit}. Exact observations are available in the chart data table below.":{"ro":"Axa orizontală: {period}. Axa verticală: {unit}. Observațiile exacte sunt disponibile în tabelul de date de sub grafic.","ar":"المحور الأفقي: {period}. المحور العمودي: {unit}. تتوفر المشاهدات الدقيقة في جدول البيانات أسفل الرسم."},"95% prediction interval":{"ro":"Interval de predicție de 95%","ar":"فاصل تنبؤ بنسبة 95%"},"95% lower":{"ro":"Limită inferioară 95%","ar":"الحد الأدنى 95%"},"95% upper":{"ro":"Limită superioară 95%","ar":"الحد الأعلى 95%"},"95% interval":{"ro":"Interval 95%","ar":"فاصل 95%"},"to":{"ro":"până la","ar":"إلى"},"Hover or tap a line for its saved value. With the chart focused, use left and right arrows for periods, up and down for series, and Escape to close the details.":{"ro":"Treci cursorul peste o linie sau atinge-o pentru valoarea salvată. Cu graficul focalizat, folosește săgețile stânga/dreapta pentru perioade, sus/jos pentru serii și Escape pentru a închide detaliile.","ar":"مرّر المؤشر فوق الخط أو المسه لعرض القيمة المحفوظة. بعد تركيز الرسم، استخدم سهمي اليمين واليسار للفترات والأعلى والأسفل للسلاسل وEscape لإغلاق التفاصيل."},"View chart values":{"ro":"Vezi valorile graficului","ar":"اعرض قيم الرسم"},"Real GDP per capita":{"ro":"PIB real pe persoană","ar":"الناتج المحلي الإجمالي الحقيقي للفرد"},"Manufacturing value added":{"ro":"Valoarea adăugată a industriei prelucrătoare","ar":"القيمة المضافة للصناعة التحويلية"},"% per year":{"ro":"% pe an","ar":"% سنويًا"},"% of GDP":{"ro":"% din PIB","ar":"% من الناتج المحلي الإجمالي"},"constant 2015 USD":{"ro":"USD la prețurile constante din 2015","ar":"دولار أمريكي بأسعار 2015 الثابتة"},"USD per person · 2015 prices":{"ro":"USD pe persoană · prețuri 2015","ar":"دولار أمريكي للفرد · أسعار 2015"},"Reported national accounts; may include estimates. Missing observations stay missing.":{"ro":"Conturi naționale raportate; pot include estimări. Observațiile lipsă rămân lipsă.","ar":"حسابات قومية معلنة قد تتضمن تقديرات. تبقى المشاهدات المفقودة مفقودة."},"World Bank staff-derived estimate; not oil GDP or fiscal revenue. Missing observations stay missing.":{"ro":"Estimare calculată de specialiștii Băncii Mondiale; nu reprezintă PIB-ul petrolier sau veniturile fiscale. Observațiile lipsă rămân lipsă.","ar":"تقدير أعده موظفو البنك الدولي؛ وليس الناتج النفطي أو الإيرادات المالية. تبقى المشاهدات المفقودة مفقودة."},"{label} in {units}":{"ro":"{label}, în {units}","ar":"{label}، بوحدة {units}"},"{label} · {units}. Iraq has {count} available annual values{window}. {note}":{"ro":"{label} · {units}. Irakul are {count} valori anuale disponibile{window}. {note}","ar":"{label} · {units}. للعراق {count} قيمة سنوية متاحة{window}. {note}"},"Saved monthly revenue forecast in nominal trillion IQD":{"ro":"Prognoza lunară salvată a veniturilor, în trilioane IQD nominale","ar":"التنبؤ المحفوظ للإيرادات الشهرية بتريليون دينار عراقي اسمي"},"nominal trillion IQD":{"ro":"trilioane IQD nominale","ar":"تريليون دينار عراقي اسمي"},"Revenue · trillion IQD":{"ro":"Venituri · trilioane IQD","ar":"الإيرادات · تريليون دينار عراقي"},"{year} baseline balance":{"ro":"Sold de referință {year}","ar":"الرصيد المرجعي {year}"},"{year} scenario balance":{"ro":"Sold în scenariu {year}","ar":"رصيد السيناريو {year}"},"of baseline GDP":{"ro":"din PIB-ul de referință","ar":"من الناتج المحلي الإجمالي المرجعي"},"of fixed baseline GDP":{"ro":"din PIB-ul fix de referință","ar":"من الناتج المحلي الإجمالي المرجعي الثابت"},"Change in balance":{"ro":"Schimbarea soldului","ar":"تغير الرصيد"},"percentage points":{"ro":"puncte procentuale","ar":"نقاط مئوية"},"IMF baseline":{"ro":"Scenariu de referință FMI","ar":"المسار المرجعي لصندوق النقد الدولي"},"My scenario":{"ro":"Scenariul meu","ar":"السيناريو الخاص بي"},"Conditional annual fiscal balance as percent of fixed GDP":{"ro":"Sold fiscal anual condiționat, ca procent din PIB-ul fix","ar":"الرصيد المالي السنوي المشروط كنسبة من الناتج المحلي الإجمالي الثابت"},"% of fixed baseline GDP":{"ro":"% din PIB-ul fix de referință","ar":"% من الناتج المحلي الإجمالي المرجعي الثابت"},"Budget balance · % of GDP":{"ro":"Sold bugetar · % din PIB","ar":"الرصيد · % من الناتج المحلي"},"I put the three features on a common scale so that their different units do not decide the ranking.":{"ro":"Aduc cele trei caracteristici la o scară comună, astfel încât unitățile diferite să nu determine clasamentul.","ar":"أضع الخصائص الثلاث على مقياس مشترك كي لا تحدد وحداتها المختلفة الترتيب."},"Choose at least one positive weight to calculate a ranking. All loaded countries are still listed below.":{"ro":"Alege cel puțin o pondere pozitivă pentru calcularea clasamentului. Toate țările încărcate rămân enumerate mai jos.","ar":"اختر وزنًا موجبًا واحدًا على الأقل لحساب الترتيب. تبقى جميع البلدان المحمّلة معروضة أدناه."},"REF":{"ro":"REF","ar":"مرجع"},"reference country":{"ro":"țară de referință","ar":"البلد المرجعي"},"The saved preview has an unexpected data format.":{"ro":"Previzualizarea salvată are un format de date neașteptat.","ar":"تنسيق بيانات المعاينة المحفوظة غير متوقع."},"The saved scenario contains an incomplete baseline.":{"ro":"Scenariul salvat conține un reper incomplet.","ar":"يحتوي السيناريو المحفوظ على مسار مرجعي غير مكتمل."},"The saved country comparisons are incomplete.":{"ro":"Comparațiile salvate între țări sunt incomplete.","ar":"مقارنات البلدان المحفوظة غير مكتملة."},"The saved preview could not load.":{"ro":"Previzualizarea salvată nu s-a putut încărca.","ar":"تعذر تحميل المعاينة المحفوظة."},"The saved preview took too long to load.":{"ro":"Încărcarea previzualizării salvate a durat prea mult.","ar":"استغرق تحميل المعاينة المحفوظة وقتًا أطول من اللازم."},"You can retry, or read the research plan below.":{"ro":"Poți reîncerca sau poți citi planul de cercetare de mai jos.","ar":"يمكنك إعادة المحاولة أو قراءة خطة البحث أدناه."},"Select language":{"ro":"Alege limba","ar":"اختر اللغة"},"English":{"ro":"Engleză","ar":"الإنجليزية"},"Romanian":{"ro":"Română","ar":"الرومانية"},"Arabic":{"ro":"Arabă","ar":"العربية"},"Iraq":{"ro":"Irak","ar":"العراق"},"Angola":{"ro":"Angola","ar":"أنغولا"},"United Arab Emirates":{"ro":"Emiratele Arabe Unite","ar":"الإمارات العربية المتحدة"},"Azerbaijan":{"ro":"Azerbaidjan","ar":"أذربيجان"},"Algeria":{"ro":"Algeria","ar":"الجزائر"},"Iran, Islamic Rep.":{"ro":"Iran","ar":"إيران"},"Kazakhstan":{"ro":"Kazahstan","ar":"كازاخستان"},"Kuwait":{"ro":"Kuweit","ar":"الكويت"},"Nigeria":{"ro":"Nigeria","ar":"نيجيريا"},"Oman":{"ro":"Oman","ar":"عُمان"},"Qatar":{"ro":"Qatar","ar":"قطر"},"Saudi Arabia":{"ro":"Arabia Saudită","ar":"السعودية"},"Country selection":{"ro":"Selecția țărilor","ar":"اختيار البلدان"},"Show selected only":{"ro":"Arată doar țările selectate","ar":"اعرض البلدان المحددة فقط"},"Show all countries":{"ro":"Arată toate țările","ar":"اعرض جميع البلدان"},"Select country lines to focus on them. Select several to compare, or show only your selection.":{"ro":"Selectează liniile țărilor pentru a le evidenția. Alege mai multe pentru comparație sau arată doar selecția ta.","ar":"حدد خطوط البلدان للتركيز عليها. اختر عدة بلدان للمقارنة أو اعرض البلدان المحددة فقط."},"All {count} countries are visible.":{"ro":"Toate cele {count} țări sunt vizibile.","ar":"جميع البلدان الـ{count} ظاهرة."},"Focused: {countries}. All countries remain visible.":{"ro":"Evidențiate: {countries}. Toate țările rămân vizibile.","ar":"التركيز على: {countries}. تبقى جميع البلدان ظاهرة."},"Showing only: {countries}.":{"ro":"Sunt afișate doar: {countries}.","ar":"يُعرض فقط: {countries}."},"Choose countries from the legend to filter the chart.":{"ro":"Alege țări din legendă pentru a filtra graficul.","ar":"اختر بلدانًا من مفتاح الرسم لتصفية المخطط."},"Select {country}":{"ro":"Selectează {country}","ar":"حدد {country}"},"From a question":{"ro":"De la o întrebare","ar":"من سؤال"},"to a":{"ro":"la un","ar":"إلى"},"working system.":{"ro":"sistem funcțional.","ar":"نظام يعمل."},"How I am turning my questions about Iraq into a careful study and an application I can explain, test and keep developing.":{"ro":"Cum transform întrebările mele despre Irak într-un studiu atent și o aplicație pe care o pot explica, testa și dezvolta în continuare.","ar":"كيف أحول أسئلتي عن العراق إلى دراسة دقيقة وتطبيق أستطيع شرحه واختباره ومواصلة تطويره."},"CASE STUDY":{"ro":"STUDIU DE CAZ","ar":"دراسة الحالة"},"Iraq since 2003":{"ro":"Irakul din 2003","ar":"العراق منذ عام 2003"},"SOFTWARE":{"ro":"SOFTWARE","ar":"البرنامج"},"An economic analysis system":{"ro":"Un sistem de analiză economică","ar":"نظام للتحليل الاقتصادي"},"CURRENT STATUS":{"ro":"STADIUL ACTUAL","ar":"الحالة الحالية"},"Provisional title · coordinator agreed":{"ro":"Titlu provizoriu · coordonator confirmat","ar":"عنوان حالي · موافقة المشرف على الإشراف"},"Professor Uscatu has agreed to coordinate my thesis. The revised title and final scope still need his confirmation.":{"ro":"Profesorul Uscatu a acceptat să îmi coordoneze lucrarea. Titlul revizuit și delimitarea finală necesită încă acordul său.","ar":"وافق الأستاذ Uscatu على الإشراف على مشروع تخرجي. ما زال العنوان المعدل والنطاق النهائي بحاجة إلى تأكيده."},"See the data and try the saved results.":{"ro":"Vezi datele și încearcă rezultatele salvate.","ar":"اطّلع على البيانات وجرّب النتائج المحفوظة."},"HOBBIES":{"ro":"PASIUNI","ar":"الهوايات"},"Why I value my professors' guidance":{"ro":"De ce apreciez îndrumarea profesorilor mei","ar":"لماذا أقدّر توجيه أساتذتي"},"Professor Uscatu and Professor Davidescu have both agreed to work with me on this project. I respect them greatly, and I look forward to learning from them and building something I can be proud of.":{"ro":"Profesorul Uscatu și profesoara Davidescu au acceptat amândoi să lucreze cu mine la acest proiect. Îi respect foarte mult și abia aștept să învăț de la ei și să construiesc ceva de care pot fi mândru.","ar":"وافق الأستاذ Uscatu والأستاذة Davidescu على العمل معي في هذا المشروع. أحترمهما كثيرًا، وأتطلع إلى التعلم منهما وبناء عمل أستطيع أن أفخر به."},"I look forward to Professor Uscatu's guidance on the software: clear modules, sensible storage, reliable algorithms and an application that runs smoothly. I want to understand the code well enough to explain and defend it myself.":{"ro":"Aștept cu interes îndrumarea profesorului Uscatu pentru partea software: module clare, stocare potrivită, algoritmi fiabili și o aplicație care funcționează fluent. Vreau să înțeleg codul suficient de bine pentru a-l explica și susține singur.","ar":"أتطلع إلى توجيه الأستاذ Uscatu في الجانب البرمجي: وحدات واضحة وتخزين مناسب وخوارزميات موثوقة وتطبيق يعمل بسلاسة. أريد فهم الكود بما يكفي لشرحه ومناقشته بنفسي."},"I look forward to Professor Davidescu's insight into the data, statistical methods and interpretation. Her guidance will help me ask stronger questions, review the models carefully and understand what the results really mean.":{"ro":"Aștept cu interes perspectiva profesoarei Davidescu asupra datelor, metodelor statistice și interpretării. Îndrumarea ei mă va ajuta să formulez întrebări mai bune, să verific modelele atent și să înțeleg ce înseamnă cu adevărat rezultatele.","ar":"أتطلع إلى رؤى الأستاذة Davidescu حول البيانات والأساليب الإحصائية والتفسير. سيساعدني توجيهها على طرح أسئلة أقوى ومراجعة النماذج بعناية وفهم المعنى الحقيقي للنتائج."},"I want their advice to challenge my ideas and help me grow as a programmer and researcher. The title and final scope will be refined with Professor Uscatu as the project develops.":{"ro":"Vreau ca sfaturile lor să îmi pună ideile la încercare și să mă ajute să cresc ca programator și cercetător. Titlul și delimitarea finală vor fi rafinate cu profesorul Uscatu pe măsură ce proiectul evoluează.","ar":"أريد أن تختبر نصائحهما أفكاري وتساعدني على التطور كمبرمج وباحث. سأراجع العنوان والنطاق النهائي مع الأستاذ Uscatu مع تطور المشروع."},"The foundation is in place: checked data processing, monthly analysis and forecast comparisons, yearly development context, clear scenarios and a working Python application.":{"ro":"Baza este pregătită: procesare verificată a datelor, analiză lunară și comparații ale prognozelor, context anual al dezvoltării, scenarii clare și o aplicație Python funcțională.","ar":"الأساس جاهز: معالجة بيانات مُراجعة، وتحليل شهري ومقارنة تنبؤات، وسياق سنوي للتنمية، وسيناريوهات واضحة، وتطبيق Python يعمل."},"Next, I want to review the data warnings and model checks, improve the database and application, and investigate spending categories where comparable records are available. I will keep the thesis focused enough to finish and understand it properly, while leaving room for the program to grow.":{"ro":"În continuare vreau să revizuiesc avertismentele datelor și verificările modelelor, să îmbunătățesc baza de date și aplicația și să investighez categoriile de cheltuieli cu evidențe comparabile. Voi păstra lucrarea suficient de concentrată pentru a o finaliza și înțelege bine, lăsând loc programului să crească.","ar":"أريد بعد ذلك مراجعة تنبيهات البيانات وفحوص النماذج وتحسين قاعدة البيانات والتطبيق ودراسة فئات الإنفاق التي تتوفر لها سجلات قابلة للمقارنة. سأحافظ على نطاق يسمح بإكمال البحث وفهمه جيدًا، مع ترك مجال لتوسع البرنامج."},"I can't wait to see what my teachers cook up for me: ideas to add, questions to explore and ways to make this work better. The sky is the limit for where I hope to take it. I will put all the passion I have into making this a useful tool for anyone interested in understanding a country's economy, just as I am trying to understand my own.":{"ro":"Abia aștept să văd ce idei vor pregăti profesorii mei pentru mine: lucruri de adăugat, întrebări de explorat și moduri de a îmbunătăți proiectul. Cerul este limita pentru ceea ce sper să devină. Îmi voi pune toată pasiunea în a-l transforma într-un instrument util oricui vrea să înțeleagă economia unei țări, așa cum încerc eu să o înțeleg pe a mea.","ar":"لا أطيق الانتظار لأرى ما سيحضّره أساتذتي لي من أفكار أضيفها وأسئلة أستكشفها وطرق أحسّن بها هذا العمل. السماء هي الحد لما أطمح أن أصل إليه. سأضع كل شغفي في جعله أداة مفيدة لكل من يهتم بفهم اقتصاد بلد، كما أحاول أنا فهم اقتصاد بلدي."}};
  const languages = ["en", "ro", "ar"], storageKey = "nooruldeen-language";
  const normalize = value => String(value).replace(/\s+/g, " ").trim();
  let language = "en";
  const nodes = [], attributes = [], links = [];
  const title = document.title, description = document.querySelector('meta[name="description"]');
  const descriptionSource = description?.content;
  function translate(source, values = {}) {
    const key = normalize(source);
    let value = language === "en" ? key : (catalog[key]?.[language] ?? key);
    // Publication dates change at build time; they do not require a new translation.
    const publication = key.match(/^Published (\d{4}-\d{2}-\d{2}) · (.*)$/);
    if (publication && language !== "en") {
      value = (language === "ro" ? "Publicat la " : "نُشر في ") + publication[1] + " · " +
        (language === "ro" ? "Datele fiscale lunare se încheie în iunie 2026 · Surse salvate: 10 și 12 octombrie 2026" : "تنتهي بيانات المالية الشهرية في يونيو 2026 · نسخ المصادر: 10 و12 أكتوبر 2026");
    }
    return value.replace(/\{([a-z_]+)\}/g, (_, name) => String(values[name] ?? "{" + name + "}"));
  }
  function initial() {
    const query = new URLSearchParams(location.search).get("lang");
    if (languages.includes(query)) return query;
    try { const saved = localStorage.getItem(storageKey); if (languages.includes(saved)) return saved; } catch (_) {}
    return "en";
  }
  function collect() {
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    while (walker.nextNode()) {
      const node = walker.currentNode;
      if (node.parentElement.closest("script, style, .language-switcher") || !node.textContent.trim()) continue;
      nodes.push([node, node.textContent]);
    }
    document.querySelectorAll("[aria-label], [alt], [title]").forEach(element => {
      for (const name of ["aria-label", "alt", "title"]) {
        if (element.hasAttribute(name)) attributes.push([element, name, element.getAttribute(name)]);
      }
    });
    document.querySelectorAll("a[href]").forEach(link => {
      const source = link.getAttribute("href"), url = new URL(source, location.href);
      if (url.origin === location.origin && !source.startsWith("#")) links.push([link, source]);
    });
  }
  function arabicFont() {
    if (document.getElementById("thesis-arabic-font")) return;
    const link = document.createElement("link"); link.id = "thesis-arabic-font"; link.rel = "stylesheet";
    link.href = "https://fonts.googleapis.com/css2?family=Noto+Sans+Arabic:wght@400;500;600;700&display=swap";
    document.head.appendChild(link);
  }
  function setLanguage(next, updateUrl = true) {
    if (!languages.includes(next)) return;
    language = next; document.documentElement.lang = next; document.documentElement.dir = next === "ar" ? "rtl" : "ltr";
    if (next === "ar") arabicFont();
    nodes.forEach(([node, source]) => {
      const leading = source.match(/^\s*/)[0], trailing = source.match(/\s*$/)[0];
      node.textContent = leading + translate(source) + trailing;
    });
    attributes.forEach(([element, name, source]) => element.setAttribute(name, translate(source)));
    document.title = translate(title); if (description) description.content = translate(descriptionSource);
    links.forEach(([link, source]) => { const url = new URL(source, location.href); url.searchParams.set("lang", next); link.href = url.pathname + url.search + url.hash; });
    document.querySelectorAll("[data-thesis-lang]").forEach(button => {
      button.setAttribute("aria-pressed", String(button.dataset.thesisLang === next)); button.title = translate(button.dataset.languageName);
    });
    document.querySelector(".language-switcher").setAttribute("aria-label", translate("Select language"));
    try { localStorage.setItem(storageKey, next); } catch (_) {}
    if (updateUrl) { const url = new URL(location.href); url.searchParams.set("lang", next); history.replaceState(null, "", url.pathname + url.search + url.hash); }
    window.dispatchEvent(new Event("noor-thesis-language"));
  }
  const switcher = document.createElement("nav"); switcher.className = "language-switcher";
  [["en", "EN", "English"], ["ro", "RO", "Romanian"], ["ar", "عربي", "Arabic"]].forEach(([code, label, name]) => {
    const button = document.createElement("button"); button.type = "button"; button.textContent = label; button.lang = code;
    button.dataset.thesisLang = code; button.dataset.languageName = name; button.addEventListener("click", () => setLanguage(code)); switcher.appendChild(button);
  });
  const header = document.querySelector(".topline"); header.insertBefore(switcher, header.querySelector(".topline-contact"));
  collect();
  const contents = document.querySelector(".plan-toc");
  if (contents && window.matchMedia("(max-width:900px)").matches) contents.open = false;
  window.noorThesisI18n = {t:translate, get language() { return language; }, get locale() { return {en:"en-GB", ro:"ro-RO", ar:"ar-IQ-u-nu-latn"}[language]; }};
  setLanguage(initial(), false);
  window.addEventListener("popstate", () => setLanguage(initial(), false));
})();
